import { useEffect, useState } from 'react';
import { me as meApi } from '@/api/endpoints.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { localTimeZone } from '@/lib/format.js';
import { platform } from '@/lib/platform/index.js';
import type { ReminderStatus } from '@/lib/platform/types.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { setReminder } from '@/db/mutations.js';
import { syncSoon } from '@/sync/store.js';
import { enablePush, toCurrentUser, useAuth } from '@/features/auth/session.js';
import { useBrowserPush } from './browserPush.js';
import { LOADING, loadSettingsScreen } from './data.js';
import { startReminder, syncReminder } from './reminders.js';
import { saveSettings } from './save.js';
import { Section, StatusLine, SubPage, SwitchRow } from './SettingsKit.js';
import { useSay } from './useSay.js';
import styles from './Settings.module.css';

/**
 * Notifications: everything Lexpad may send and where it arrives. The daily
 * reminder, product news in the apps and notifications in this browser come
 * first; the three e-mails the account can turn off follow under their
 * own heading, because they reach a different place.
 */
export function NotificationSettings(): React.JSX.Element {
  const { settings } = useLiveQuery(loadSettingsScreen, LOADING, []);
  const user = useAuth((state) => state.user);
  const setUser = useAuth((state) => state.setUser);
  // Notifications in this browser: web only, and only where the server can send them.
  const browserPush = useBrowserPush();
  const { status, failed, say } = useSay();

  // What the host said the last time the reminder was scheduled, so the
  // screen can explain a reminder that cannot arrive.
  const [reminderStatus, setReminderStatus] = useState<ReminderStatus | undefined>();
  // An empty value turns the reminder off; a time turns it on or moves it.
  const changeReminder = (value: string): void => {
    void setReminder(value === '' ? null : value, localTimeZone())
      .then(() => syncSoon())
      .then(() => (value === '' ? syncReminder() : startReminder()))
      .then(setReminderStatus);
  };
  useEffect(() => {
    let live = true;
    void syncReminder().then((next) => {
      if (live) setReminderStatus(next);
    });
    return () => {
      live = false;
    };
  }, []);

  return (
    <SubPage title={t('settings.page.notifications')}>
      <div className={styles.group}>
        <div className={cx(styles.row, styles.rowStatic)}>
          <span className={styles.labelStack}>
            <span className={styles.label}>{t('settings.reminder')}</span>
            <span className={styles.note}>
              {settings.reminderTime === undefined
                ? t('settings.reminderOff')
                : t('settings.reminderOn', { time: settings.reminderTime })}
            </span>
          </span>
          <span className={styles.reminderControls}>
            {/*
              iOS's time picker cannot be emptied (its Reset puts the current
              time back), so a set reminder needs its own way off.
            */}
            {settings.reminderTime !== undefined && (
              <button
                type="button"
                className={styles.inlineButton}
                onClick={() => {
                  changeReminder('');
                }}
              >
                {t('settings.reminderTurnOff')}
              </button>
            )}
            <input
              type="time"
              className={styles.time}
              aria-label={t('settings.reminder')}
              value={settings.reminderTime ?? ''}
              onChange={(event) => {
                changeReminder(event.target.value);
              }}
            />
          </span>
        </div>
        {reminderStatus === 'unsupported' && <p className={styles.groupNote}>{t('settings.reminderWeb')}</p>}
        {reminderStatus === 'denied' && <p className={styles.groupNote}>{t('settings.reminderDenied')}</p>}
        {platform.push.available && (
          <>
            <SwitchRow
              label={t('settings.pushNews')}
              checked={settings.pushNews !== false}
              onChange={(pushNews) => {
                saveSettings({ pushNews });
                // Turning it on is a moment the learner chose, so this is
                // where the phone may ask for notification permission.
                if (pushNews) void enablePush().catch(() => undefined);
              }}
            />
            <p className={styles.groupNote}>{t('settings.pushNewsNote')}</p>
          </>
        )}
        {browserPush.view.kind === 'install' && (
          <p className={styles.groupNote}>{t('settings.browserPushInstall')}</p>
        )}
        {browserPush.view.kind === 'switch' && (
          <>
            <SwitchRow
              label={t('settings.browserPush')}
              checked={browserPush.view.on}
              onChange={browserPush.toggle}
            />
            <p
              className={styles.groupNote}
              role={browserPush.view.problem || browserPush.view.busy ? 'status' : undefined}
            >
              {browserPush.view.busy && !browserPush.view.on
                ? // Chrome often asks with a small icon in the address bar
                  // rather than a box, and until it is answered nothing
                  // here can move: say where the question is.
                  t('settings.browserPushAsking')
                : browserPush.view.problem === 'denied'
                  ? t('settings.browserPushDenied')
                  : browserPush.view.problem === 'failed'
                    ? t('settings.browserPushFailed')
                    : t('settings.browserPushNote')}
            </p>
          </>
        )}
      </div>

      <Section title={t('settings.emailHeading')}>
        <div className={styles.group}>
          <SwitchRow
            label={t('settings.emailNudges')}
            // Absent means on, as on the server. Only this write sends it
            // (see settingsPayload), so saving anything else never undoes
            // an "off" given from an e-mail this device has not heard of.
            checked={settings.emailNudges !== false}
            onChange={(emailNudges) => {
              saveSettings({ emailNudges });
            }}
          />
          <p className={styles.groupNote}>{t('settings.emailNudgesNote')}</p>
          <SwitchRow
            label={t('settings.weekly')}
            checked={settings.weeklySummary}
            onChange={(weeklySummary) => {
              saveSettings({ weeklySummary });
            }}
          />
          <p className={styles.groupNote}>{t('settings.weeklyNote')}</p>
          <SwitchRow
            label={t('settings.news')}
            checked={user?.marketingOptIn === true}
            onChange={(checked) => {
              meApi
                .update({ marketingOptIn: checked })
                .then((updated) => setUser(toCurrentUser(updated)))
                .catch(() => {
                  say(t('error.generic'), true);
                });
            }}
          />
          {/* Each note sits under its own switch: three notes under the card
              left the reader to work out which was which. */}
          <p className={styles.groupNote}>{t('settings.newsNote')}</p>
        </div>
      </Section>

      <StatusLine status={status} failed={failed} />
    </SubPage>
  );
}
