import { useState } from 'react';
import { defaultSettings, type GradingMode, type NewWordOrder } from '@lexpad/core';
import { t, type MessageKey } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { toggleCardType } from '@/db/mutations.js';
import { syncSoon } from '@/sync/store.js';
import { SRS_OFF, loadSrsView, shows, type SrsView } from '@/features/schedule/data.js';
import { learnShows, rememberMoreOptions, setTipsOff } from '@/features/learn/state.js';
import { useLearn } from '@/features/learn/useLearn.js';
import { setCelebrationsOff } from '@/features/celebrate/state.js';
import { useCelebrate } from '@/features/celebrate/useCelebrate.js';
import { getMeta } from '@/db/schema.js';
import { MoreOptions } from './MoreOptions.js';
import { LANGUAGE_NAMES, LOADING, loadSettingsScreen } from './data.js';
import { CARD_TYPES, GRADING } from './options.js';
import { settingsPath } from './paths.js';
import { saveSettings } from './save.js';
import { NavRow, Section, Slider, SubPage, SwitchRow } from './SettingsKit.js';
import { StreakFreezeRow } from '@/features/streak/StreakFreezeRow.js';
import { PRACTICE_STYLES, STYLE_LABELS, stylesOf, withStyle } from './style.js';
import styles from './Settings.module.css';

const ORDER_LABELS: Record<NewWordOrder, MessageKey> = {
  newest: 'settings.newNewest',
  start: 'settings.newStart',
  shuffle: 'settings.newShuffle',
};

/**
 * Practice: how much a day brings, which kinds of card it is made of, how
 * strictly typing is marked and which new words come first; then sound,
 * which is part of how a session feels. Which notebooks a session draws
 * from is chosen in the notebook sheet, beside the notebooks themselves.
 */
export function PracticeSettings(): React.JSX.Element {
  const { settings, notebook } = useLiveQuery(loadSettingsScreen, LOADING, []);
  // Null until read: the rows that fold under "More options" wait for it, so
  // they never show for a frame and then fold away.
  const srsRead = useLiveQuery<SrsView | null>(loadSrsView, null, []);
  const srs = srsRead ?? SRS_OFF;
  const targetName = LANGUAGE_NAMES[notebook?.targetLang ?? 'en'];
  const chosenStyles = stylesOf(settings.cardTypes);
  // The new learner's journey (SRS v2): "Show tips", and the rarely used
  // controls folded under "More options" (§5.2).
  const learnOn = learnShows(srs);
  const learn = useLearn();
  const celebrate = useCelebrate();
  const remembered = useLiveQuery(async () => (await getMeta('moreOptions'))?.practice === true, false, []);
  const [moreOverride, setMoreOverride] = useState<boolean | undefined>(undefined);

  const cardTypeRows = CARD_TYPES.map((type) => {
    const on = settings.cardTypes.includes(type.value);
    return (
      <SwitchRow
        key={type.value}
        label={t(type.labelKey)}
        checked={on}
        dim={!on}
        onChange={() => {
          void toggleCardType(type.value).then(() => syncSoon());
        }}
      />
    );
  });
  const typingRow = (
    <div className={cx(styles.row, styles.rowStatic)}>
      <span className={styles.label}>{t('settings.typedGrading')}</span>
      <select
        className={styles.select}
        aria-label={t('settings.typedGrading')}
        value={settings.typedGrading}
        onChange={(event) => {
          saveSettings({ typedGrading: event.target.value as GradingMode });
        }}
      >
        {GRADING.map((entry) => (
          <option key={entry.value} value={entry.value}>
            {t(entry.labelKey)}
          </option>
        ))}
      </select>
    </div>
  );
  // Stacked, not side by side: "From the start of the notebook" makes the
  // closed select wide enough to squeeze the label into four lines of one
  // word each.
  const orderRow = (
    <div className={cx(styles.row, styles.rowStatic, styles.rowStacked)}>
      <span className={styles.label}>{t('settings.newWordOrder')}</span>
      <select
        className={styles.select}
        aria-label={t('settings.newWordOrder')}
        value={settings.newWordOrder}
        onChange={(event) => {
          saveSettings({ newWordOrder: event.target.value as NewWordOrder });
        }}
      >
        <option value="newest">{t('settings.newNewest')}</option>
        <option value="start">{t('settings.newStart')}</option>
        <option value="shuffle">{t('settings.newShuffle')}</option>
      </select>
    </div>
  );

  // What differs from a new account's settings is named on the row and opens it.
  const defaults = defaultSettings();
  const changed = [
    ...CARD_TYPES.filter((type) => !settings.cardTypes.includes(type.value)).map((type) =>
      t('settings.changedItem', { name: t(type.labelKey), value: t('schedule.off') }),
    ),
    ...(settings.typedGrading === defaults.typedGrading
      ? []
      : [
          t('settings.changedItem', {
            name: t('settings.typedGrading'),
            value: t(
              GRADING.find((entry) => entry.value === settings.typedGrading)?.labelKey ??
                'settings.gradingOneTypo',
            ),
          }),
        ]),
    ...(settings.newWordOrder === defaults.newWordOrder
      ? []
      : [
          t('settings.changedItem', {
            name: t('settings.newWordOrder'),
            value: t(ORDER_LABELS[settings.newWordOrder]),
          }),
        ]),
  ];
  const moreOpen = moreOverride ?? (changed.length > 0 || remembered);

  return (
    <SubPage title={t('settings.page.practice')}>
      {/* SRS v2: how the notebook's words come back, one tap away from the
          limits that shape a day. */}
      {srs.enabled && notebook !== undefined && (
        <div className={styles.group}>
          <NavRow
            to={settingsPath('schedule')}
            icon="progress"
            label={t('schedule.rowIn', { notebook: notebook.title })}
          />
        </div>
      )}
      <Section title={t('settings.practice')}>
        <div className={styles.group}>
          <Slider
            label={t('settings.newPerDay')}
            value={settings.newPerDay}
            min={5}
            max={40}
            step={5}
            onChange={(newPerDay) => {
              saveSettings({ newPerDay });
            }}
          />
          {shows(srs, 'dailyNewLimit') && <p className={styles.groupNote}>{t('schedule.newPerDayNote')}</p>}
          <Slider
            label={t('settings.sessionCap')}
            value={settings.sessionCap}
            min={10}
            max={60}
            step={5}
            onChange={(sessionCap) => {
              saveSettings({ sessionCap });
            }}
          />
          <div className={cx(styles.row, styles.rowStatic)}>
            <span className={styles.label}>{t('settings.practiceStyle')}</span>
            {/* Several at once, because the three divide the card types
                between them and practising two of them is an ordinary thing
                to want. There is no "mixed": that was all three, which is
                now just all three chosen. */}
            <div className={styles.tray} role="group" aria-label={t('settings.practiceStyle')}>
              {PRACTICE_STYLES.map((style) => {
                const on = chosenStyles.includes(style);
                return (
                  <button
                    key={style}
                    type="button"
                    className={cx(styles.trayButton, on && styles.trayOn)}
                    aria-pressed={on}
                    onClick={() => {
                      saveSettings({ cardTypes: withStyle(style, !on, settings.cardTypes) });
                    }}
                  >
                    {t(STYLE_LABELS[style])}
                  </button>
                );
              })}
            </div>
          </div>
          <p className={styles.groupNote}>{t('settings.practiceStyleNote')}</p>
          {srsRead !== null && !learnOn && (
            <>
              {cardTypeRows}
              {typingRow}
              {orderRow}
            </>
          )}
        </div>
      </Section>

      {learnOn && (
        <MoreOptions
          summary={t('practice.moreSummary')}
          changed={changed}
          open={moreOpen}
          onToggle={(open) => {
            setMoreOverride(open);
            void rememberMoreOptions('practice', open);
          }}
        >
          <div className={styles.group}>
            {cardTypeRows}
            {typingRow}
            {orderRow}
          </div>
        </MoreOptions>
      )}

      {/* SRS v2: streak freeze, when it is switched on for this account. */}
      <StreakFreezeRow />
      <Section title={t('settings.sound')}>
        <div className={styles.group}>
          <SwitchRow
            label={t('settings.autoSpeak', { language: targetName })}
            checked={settings.autoSpeak}
            onChange={(autoSpeak) => {
              saveSettings({ autoSpeak });
            }}
          />
          <SwitchRow
            label={t('settings.speakExamples')}
            checked={settings.speakExamples}
            onChange={(speakExamples) => {
              saveSettings({ speakExamples });
            }}
          />
        </div>
      </Section>

      {/* Celebrations (features/celebrate): on unless turned off here, on
          this device. Off means no confetti and no moments; the plain facts
          (the ring, the counts) stay, because they are information. */}
      {celebrate.on && celebrate.state !== null && (
        <div className={styles.group}>
          <SwitchRow
            label={t('settings.celebrations')}
            checked={!celebrate.state.off}
            onChange={(show) => {
              void setCelebrationsOff(!show);
            }}
          />
          <p className={styles.groupNote}>{t('settings.celebrationsNote')}</p>
        </div>
      )}

      {/* The new learner's journey: a short hint the first time something is
          met. Off means no tips at all; How Lexpad works stays. */}
      {learnOn && learn.tips !== null && (
        <div className={styles.group}>
          <SwitchRow
            label={t('settings.showTips')}
            checked={!learn.tips.off}
            onChange={(show) => {
              void setTipsOff(!show);
            }}
          />
          <p className={styles.groupNote}>{t('settings.showTipsNote')}</p>
        </div>
      )}
    </SubPage>
  );
}
