import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth as authApi, me as meApi } from '@/api/endpoints.js';
import { ApiError, isApiError } from '@/api/errors.js';
import type { ApiUserSession } from '@/api/types.js';
import { Button } from '@/components/ui/Button.js';
import { Confirm } from '@/components/ui/Confirm.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { getLocale, t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { lastSeenLabel } from '@/lib/format.js';
import { useAuth } from '@/features/auth/session.js';
import { platform } from '@/lib/platform/index.js';
import { deviceTitle, signInMethods } from './devices.js';
import { Section, StatusLine, SubPage } from './SettingsKit.js';
import { useSay } from './useSay.js';
import styles from './Settings.module.css';

/**
 * Account: the e-mail address and whether it is confirmed, how the account
 * signs in and its password, the devices signed in to it, and the two ways
 * out — signing out and deleting the account. Both of those ask first.
 */
export function AccountSettings(): React.JSX.Element {
  const navigate = useNavigate();
  const user = useAuth((state) => state.user);
  const refreshUser = useAuth((state) => state.refreshUser);
  const signOut = useAuth((state) => state.signOut);
  const deleteAccount = useAuth((state) => state.deleteAccount);
  const hasPassword = user?.providers.includes('password') === true;
  const { status, failed, say } = useSay();

  const [confirmDelete, setConfirmDelete] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [confirmSignOut, setConfirmSignOut] = useState(false);
  const [changingPassword, setChangingPassword] = useState(false);
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [passwordBusy, setPasswordBusy] = useState(false);
  const [passwordError, setPasswordError] = useState<string | undefined>();
  // Setting a first password needs a recent sign-in; when the server asks for
  // one, the sheet offers the existing sign-out, since signing in again with
  // Google or Apple is the only proof such an account can give.
  const [passwordReauth, setPasswordReauth] = useState(false);
  // The devices list is read from the server, not the database: it is about
  // other devices, which this one cannot know.
  const [devices, setDevices] = useState<ApiUserSession[] | 'offline' | undefined>();
  // The device whose sign-out is being confirmed, and whether it is under way.
  const [revoking, setRevoking] = useState<ApiUserSession | undefined>();
  const [revokeBusy, setRevokeBusy] = useState(false);

  const loadDevices = (): void => {
    meApi
      .sessions()
      .then(setDevices)
      .catch((cause: unknown) => {
        setDevices(isApiError(cause, 'offline') ? 'offline' : []);
      });
  };
  useEffect(loadDevices, []);

  const submitPassword = (): void => {
    setPasswordBusy(true);
    setPasswordError(undefined);
    setPasswordReauth(false);
    // An account with no password is giving itself one, so there is no
    // current password to prove and no other device to sign out.
    const done = hasPassword
      ? authApi.changePassword(currentPassword, newPassword)
      : authApi.setPassword(newPassword);
    done
      .then(() => {
        setChangingPassword(false);
        setCurrentPassword('');
        setNewPassword('');
        say(hasPassword ? t('settings.passwordChanged') : t('settings.passwordSet'));
        loadDevices();
        // The account now signs in two ways; the row must say so.
        if (!hasPassword) void refreshUser();
      })
      .catch((cause: unknown) => {
        if (cause instanceof ApiError && cause.code === 'wrong_password')
          setPasswordError(t('settings.passwordWrong'));
        else if (
          cause instanceof ApiError &&
          (cause.code === 'weak_password' || cause.code === 'validation_failed')
        )
          setPasswordError(cause.message === '' ? t('settings.passwordWeak') : cause.message);
        else if (cause instanceof ApiError && cause.code === 'email_unverified')
          setPasswordError(t('settings.passwordNeedsEmail'));
        else if (cause instanceof ApiError && cause.code === 'reauth_required') {
          setPasswordError(t('settings.passwordReauth'));
          setPasswordReauth(true);
        } else if (cause instanceof ApiError && cause.code === 'delegated_session')
          setPasswordError(t('settings.passwordDelegated'));
        else setPasswordError(isApiError(cause, 'offline') ? t('error.offline') : t('error.generic'));
      })
      .finally(() => {
        setPasswordBusy(false);
      });
  };

  return (
    <SubPage title={t('settings.page.account')}>
      <div className={styles.group}>
        <div className={cx(styles.row, styles.rowStatic)}>
          <span className={styles.label}>{t('auth.email')}</span>
          <span className={styles.valueSmall}>
            {user?.email} ·{' '}
            {user?.emailVerified ? t('settings.emailConfirmed') : t('settings.emailUnconfirmed')}
          </span>
        </div>
        {user !== null && !user.emailVerified && (
          <button
            type="button"
            className={cx(styles.row, styles.button)}
            onClick={() => {
              authApi
                .resendVerification()
                .then(() => {
                  say(t('auth.verifyResent'));
                })
                .catch((cause: unknown) => {
                  if (cause instanceof ApiError && cause.code === 'rate_limited')
                    say(t('auth.verifyResendLater'), true);
                  else if (cause instanceof ApiError && cause.code === 'mail_unavailable')
                    say(t('auth.verifyMailUnavailable'), true);
                  else if (cause instanceof ApiError && cause.code === 'already_verified') void refreshUser();
                  else say(t('error.generic'), true);
                });
            }}
          >
            <span className={styles.label}>{t('settings.resendVerification')}</span>
          </button>
        )}
        {user !== null && user.providers.length > 0 && (
          <div className={cx(styles.row, styles.rowStatic)}>
            <span className={styles.label}>{t('settings.signInMethods')}</span>
            <span className={styles.valueSmall}>{signInMethods(user.providers, getLocale())}</span>
          </div>
        )}
        <button
          type="button"
          className={cx(styles.row, styles.button)}
          onClick={() => {
            // The desktop app never takes a password in its window, and its
            // session may not change one: the browser does it.
            if (platform.desktop !== undefined) {
              void platform.desktop.openInBrowser('/settings/account').catch(() => {
                say(t('error.generic'), true);
              });
              return;
            }
            setPasswordError(undefined);
            setPasswordReauth(false);
            setChangingPassword(true);
          }}
        >
          <span className={styles.label}>
            {hasPassword ? t('settings.changePassword') : t('settings.setPassword')}
          </span>
          <span className={styles.valueSmall}>
            {platform.desktop !== undefined
              ? t('settings.inYourBrowser')
              : hasPassword
                ? t('settings.changePasswordNote')
                : t('settings.setPasswordNote')}
          </span>
        </button>
      </div>

      <Section title={t('settings.devices')}>
        {/* No empty card while the list is on its way. */}
        {(devices === 'offline' || (Array.isArray(devices) && devices.length > 0)) && (
          <div className={styles.group}>
            {devices === 'offline' && (
              <div className={cx(styles.row, styles.rowStatic)}>
                <span className={cx(styles.valueSmall, styles.rowMessage)}>
                  {t('settings.devicesOffline')}
                </span>
              </div>
            )}
            {Array.isArray(devices) &&
              devices.map((device) => (
                <div key={device.id} className={cx(styles.row, styles.rowStatic)}>
                  <span className={styles.deviceText}>
                    <span className={styles.label}>{deviceTitle(device)}</span>
                    <span className={styles.valueSmall}>
                      {t('settings.deviceLastSeen', { when: lastSeenLabel(device.lastSeenAt) })}
                    </span>
                  </span>
                  {device.current ? (
                    <span className={styles.valueSmall}>{t('settings.thisDevice')}</span>
                  ) : (
                    <button
                      type="button"
                      className={styles.inlineButton}
                      onClick={() => {
                        setRevoking(device);
                      }}
                    >
                      {t('settings.signOutDevice')}
                    </button>
                  )}
                </div>
              ))}
          </div>
        )}
        <p className={styles.dataNote}>{t('settings.devicesNote')}</p>
      </Section>

      <div className={styles.group}>
        <button
          type="button"
          className={cx(styles.row, styles.button)}
          onClick={() => {
            setConfirmSignOut(true);
          }}
        >
          <span className={styles.label}>{t('settings.signOut')}</span>
          <span className={styles.valueSmall}>{user?.email}</span>
        </button>
        <button
          type="button"
          className={cx(styles.row, styles.button)}
          onClick={() => {
            setConfirmDelete(true);
          }}
        >
          <span className={cx(styles.label, styles.danger)}>{t('settings.deleteAccount')}</span>
          <span className={styles.valueSmall}>{t('settings.deleteAccountNote')}</span>
        </button>
      </div>

      <StatusLine status={status} failed={failed} />

      {revoking !== undefined && (
        <Confirm
          title={t('settings.signOutDeviceTitle', { device: deviceTitle(revoking) })}
          body={t('settings.signOutDeviceBody')}
          confirmLabel={t('settings.signOutDevice')}
          busy={revokeBusy}
          onCancel={() => {
            setRevoking(undefined);
          }}
          onConfirm={() => {
            setRevokeBusy(true);
            meApi
              .revokeSession(revoking.id)
              .then(loadDevices)
              .catch((cause: unknown) => {
                say(isApiError(cause, 'offline') ? t('error.offline') : t('error.generic'), true);
              })
              .finally(() => {
                setRevokeBusy(false);
                setRevoking(undefined);
              });
          }}
        />
      )}

      {changingPassword && (
        <Sheet
          title={hasPassword ? t('settings.changePassword') : t('settings.setPassword')}
          onClose={() => {
            if (!passwordBusy) setChangingPassword(false);
          }}
        >
          <form
            className={styles.deleteSheet}
            onSubmit={(event) => {
              event.preventDefault();
              submitPassword();
            }}
          >
            {!hasPassword && <p className={styles.dataNote}>{t('settings.setPasswordLead')}</p>}
            {hasPassword && (
              <input
                className={styles.input}
                type="password"
                autoComplete="current-password"
                placeholder={t('settings.currentPassword')}
                aria-label={t('settings.currentPassword')}
                value={currentPassword}
                onChange={(event) => {
                  setCurrentPassword(event.target.value);
                }}
              />
            )}
            <input
              className={styles.input}
              type="password"
              autoComplete="new-password"
              placeholder={t('settings.newPassword')}
              aria-label={t('settings.newPassword')}
              minLength={8}
              value={newPassword}
              onChange={(event) => {
                setNewPassword(event.target.value);
              }}
            />
            {passwordError !== undefined && (
              <p className={styles.formError} role="alert">
                {passwordError}
              </p>
            )}
            <Button
              type="button"
              size="large"
              block
              busy={passwordBusy}
              disabled={(hasPassword && currentPassword === '') || newPassword.length < 8}
              onClick={submitPassword}
            >
              {hasPassword ? t('settings.changePassword') : t('settings.setPassword')}
            </Button>
            {passwordReauth && (
              <Button
                type="button"
                variant="secondary"
                size="large"
                block
                onClick={() => {
                  setChangingPassword(false);
                  setConfirmSignOut(true);
                }}
              >
                {t('settings.signOut')}
              </Button>
            )}
          </form>
        </Sheet>
      )}

      {confirmSignOut && (
        <Confirm
          title={t('settings.signOutTitle')}
          body={t('settings.signOutBody')}
          confirmLabel={t('settings.signOut')}
          onCancel={() => {
            setConfirmSignOut(false);
          }}
          onConfirm={() => {
            setConfirmSignOut(false);
            void signOut().then((result) => {
              if (result.outcome === 'pending')
                say(t('settings.signOutPending', { count: result.pending }), true);
              else void navigate('/auth', { replace: true });
            });
          }}
        />
      )}

      {confirmDelete && (
        <Confirm
          title={t('settings.deleteTitle')}
          body={[t('settings.deleteBody'), t('settings.deleteExportFirst')]}
          confirmLabel={t('settings.deleteConfirm')}
          cancelLabel={t('settings.deleteCancel')}
          danger
          busy={deleting}
          onCancel={() => {
            setConfirmDelete(false);
          }}
          onConfirm={() => {
            setDeleting(true);
            deleteAccount()
              .then(() => {
                void navigate('/auth', { replace: true });
              })
              .catch((cause: unknown) => {
                setDeleting(false);
                setConfirmDelete(false);
                say(isApiError(cause, 'offline') ? t('error.offline') : t('settings.deleteFailed'), true);
              });
          }}
        />
      )}
    </SubPage>
  );
}
