import { useId } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import styles from './Settings.module.css';
import own from './MoreOptions.module.css';

/**
 * "More options" on a settings page (the new learner's journey, §5): the
 * rarely used controls folded under one row that names what is inside, so a
 * page shows two levels at most. Folding is not hiding: the page opens it by
 * itself when anything inside differs from its default, when another screen
 * sent the learner to a control inside, and when it was left open last time
 * on this device; and the row says what was changed. Opening it moves
 * nothing to another screen.
 */
export function MoreOptions({
  summary,
  changed,
  open,
  onToggle,
  children,
}: {
  /** What is inside, in a few words. */
  summary: string;
  /** What differs from the default, as "name: value" each, if anything. */
  changed: readonly string[];
  open: boolean;
  onToggle: (open: boolean) => void;
  children: React.ReactNode;
}): React.JSX.Element {
  const id = useId();
  return (
    <>
      <div className={styles.group}>
        <button
          type="button"
          className={cx(styles.row, styles.button, own.row)}
          aria-expanded={open}
          {...(open ? { 'aria-controls': id } : {})}
          onClick={() => {
            onToggle(!open);
          }}
        >
          <span className={own.text}>
            <span className={styles.label}>{t('settings.moreOptions')}</span>
            <span className={own.summary}>{summary}</span>
            {changed.length > 0 && (
              <span className={own.changed}>
                {t('settings.moreOptionsChanged', { list: changed.join(', ') })}
              </span>
            )}
          </span>
          <Icon name="chevronDown" size={18} weight={2} className={cx(styles.chevron, own.chevron)} />
        </button>
      </div>
      {open && (
        <div id={id} className={own.body}>
          {children}
        </div>
      )}
    </>
  );
}
