import { useNavigate } from 'react-router-dom';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { aiPausedUntil } from '@/features/ai/quota.js';
import { PlanRow } from '@/features/billing/Upgrade.js';
import { TrialOptIn } from '@/features/billing/TrialOptIn.js';
import { useBilling, usedAPromo } from '@/features/billing/state.js';
import { SubPage } from './SettingsKit.js';
import { usePlanOnOpen } from './usePlanOnOpen.js';
import styles from './Settings.module.css';

/**
 * Plan: what the account is on, and the one place outside a paywall that
 * offers Pro — through `PlanRow`, which says nothing about a price where
 * this client may not sell or the notebook is one Lexpad never charges for.
 */
export function PlanSettings(): React.JSX.Element {
  usePlanOnOpen();
  return (
    <SubPage title={t('settings.page.plan')}>
      <PlanControls />
    </SubPage>
  );
}

/**
 * The plan rows, shared by the main page and the Plan page. Whoever renders
 * it calls `usePlanOnOpen`, so the plan is read once per page.
 */
export function PlanControls(): React.JSX.Element {
  const navigate = useNavigate();
  // One promotion per account, so the way in disappears once it has been
  // used rather than staying to be refused.
  const promoSpent = useBilling((state) => usedAPromo(state.state));
  const aiResting = useLiveQuery(() => aiPausedUntil(), undefined, []) !== undefined;

  return (
    <>
      {aiResting && <p className={styles.dataNote}>{t('settings.aiResting')}</p>}
      <div className={styles.group}>
        <PlanRow
          rowClass={cx(styles.row, styles.rowStatic)}
          labelClass={styles.label}
          valueClass={styles.valueSmall}
        />
        <TrialOptIn
          rowClass={cx(styles.row, styles.rowStatic)}
          labelClass={styles.label}
          valueClass={styles.valueSmall}
        />
        {!promoSpent && (
          <button
            type="button"
            className={cx(styles.row, styles.button)}
            onClick={() => {
              void navigate('/promo');
            }}
          >
            <span className={styles.labelStack}>
              <span className={styles.label}>{t('settings.promo')}</span>
              <span className={styles.valueSmall}>{t('settings.promoNote')}</span>
            </span>
          </button>
        )}
      </div>
    </>
  );
}
