import { useEffect, useState } from 'react';
import { Button } from '@/components/ui/Button.js';
import { Confirm } from '@/components/ui/Confirm.js';
import { Icon } from '@/components/ui/Icon.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { Spinner } from '@/components/ui/Spinner.js';
import { share as shareApi } from '@/api/endpoints.js';
import { t } from '@/i18n/index.js';
import { platform } from '@/lib/platform/index.js';
import type { ApiShareLink } from '@/api/types.js';
import styles from './ShareSheet.module.css';

/**
 * The owner's side of a share: the link, a way to pass it on, and a way to
 * stop.
 *
 * Making the link is the act of opening this sheet, which is why it happens
 * without a button: somebody who tapped "Share this notebook" has already
 * said what they want. Asking again on a second open would mint a second
 * address nobody could revoke, so the server hands back the one in use.
 */
export function ShareSheet({
  notebookId,
  onClose,
}: {
  notebookId: string;
  onClose: () => void;
}): React.JSX.Element {
  const [link, setLink] = useState<ApiShareLink | undefined>();
  const [error, setError] = useState<string | undefined>();
  const [note, setNote] = useState<string | undefined>();
  const [stopping, setStopping] = useState(false);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let live = true;
    shareApi
      .start(notebookId)
      .then((made) => {
        if (live) setLink(made);
      })
      .catch(() => {
        if (live) setError(platform.network.online ? t('share.failed') : t('share.offline'));
      });
    return () => {
      live = false;
    };
  }, [notebookId]);

  const pass = (): void => {
    if (!link) return;
    void platform.share
      .link(link.url, t('share.title'))
      .then((how) => {
        setNote(how === 'copied' ? t('share.copied') : undefined);
      })
      .catch(() => {
        setNote(t('error.generic'));
      });
  };

  if (stopping) {
    return (
      <Confirm
        title={t('share.stopTitle')}
        body={t('share.stopBody')}
        confirmLabel={t('share.stop')}
        danger
        busy={busy}
        onCancel={() => {
          setStopping(false);
        }}
        onConfirm={() => {
          setBusy(true);
          shareApi
            .stop(notebookId)
            .then(onClose)
            .catch(() => {
              setBusy(false);
              setStopping(false);
              setError(platform.network.online ? t('error.generic') : t('share.offline'));
            });
        }}
      />
    );
  }

  return (
    <Sheet title={t('share.title')} onClose={onClose}>
      <div className={styles.body}>
        <p className={styles.lead}>{t('share.lead')}</p>

        {error !== undefined && <p className={styles.error}>{error}</p>}

        {error === undefined && link === undefined && (
          <div className={styles.waiting}>
            <Spinner />
            <span className={styles.note}>{t('share.making')}</span>
          </div>
        )}

        {link !== undefined && (
          <>
            {/* Readable rather than editable: the address is the thing to
                look at and pass on, not something to change. */}
            <p className={styles.link} dir="ltr">
              {link.url}
            </p>
            <Button onClick={pass}>
              <Icon name="arrowRight" size={17} weight={2.2} />
              {t('share.send')}
            </Button>
            {note !== undefined && (
              <p className={styles.note} role="status">
                {note}
              </p>
            )}
            {link.viewCount > 0 && (
              <p className={styles.note}>
                {link.viewCount === 1 ? t('share.viewsOne') : t('share.views', { count: link.viewCount })}
              </p>
            )}
            <button
              type="button"
              className={styles.stop}
              onClick={() => {
                setStopping(true);
              }}
            >
              {t('share.stop')}
            </button>
          </>
        )}
      </div>
    </Sheet>
  );
}
