import { useState } from 'react';
import { billing as billingApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { getActiveNotebook } from '@/db/repo.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { canBuyHere, cheapestPrice, freeNotebook, useBilling } from './state.js';
import { trialOptInOn } from './trial.js';
import styles from './Upgrade.module.css';

/**
 * "Try Pro free" on Settings → Plan, for an account on Free that has never
 * had a trial: no card, nothing charged, and nothing taken away when it
 * ends. It stays silent wherever an offer of Pro would (a client that may
 * not sell, no price, a notebook Lexpad never charges for), and once the
 * server has said no — closed, or this account has had Pro — it says so once
 * and goes. No length and no allowance is written: the server decides both.
 */
export function TrialOptIn({
  rowClass,
  labelClass,
  valueClass,
}: {
  rowClass: string | undefined;
  labelClass: string | undefined;
  valueClass: string | undefined;
}): React.JSX.Element | null {
  const state = useBilling((s) => s.state);
  const refresh = useBilling((s) => s.refresh);
  const notebook = useLiveQuery(getActiveNotebook, undefined, []);
  const [busy, setBusy] = useState(false);
  const [said, setSaid] = useState<{ text: string; final: boolean } | undefined>();

  const eligible =
    trialOptInOn() &&
    state !== null &&
    state.plan === 'free' &&
    state.trial === undefined &&
    state.trialEnded === undefined &&
    canBuyHere(state) &&
    cheapestPrice(state) !== undefined &&
    !freeNotebook(state, notebook?.targetLang, notebook?.meaningLang);

  if (said?.final === true) {
    return (
      <p className={styles.note} role="status">
        {said.text}
      </p>
    );
  }
  if (!eligible) return null;

  const start = (): void => {
    setBusy(true);
    setSaid(undefined);
    billingApi
      .startTrial()
      .then(async () => {
        await refresh();
        setSaid({ text: t('trial.started'), final: true });
      })
      .catch((cause: unknown) => {
        if (isApiError(cause, 'notFound')) setSaid({ text: t('trial.closed'), final: true });
        else if (isApiError(cause, 'conflict')) setSaid({ text: t('trial.used'), final: true });
        else
          setSaid({
            text: isApiError(cause, 'offline') ? t('error.offline') : t('error.generic'),
            final: false,
          });
      })
      .finally(() => {
        setBusy(false);
      });
  };

  return (
    <>
      <button type="button" className={cx(rowClass, styles.button)} disabled={busy} onClick={start}>
        <span className={labelClass}>{busy ? t('trial.starting') : t('trial.start')}</span>
        <span className={valueClass}>{t('trial.startNote')}</span>
      </button>
      {said !== undefined && (
        <p className={styles.error} role="alert">
          {said.text}
        </p>
      )}
    </>
  );
}
