import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { isApiError } from '@/api/errors.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { lastSeenLabel } from '@/lib/format.js';
import { getMeta } from '@/db/schema.js';
import { currentDevice } from '@/lib/platform/device.js';
import { platform } from '@/lib/platform/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { ConnectAssistantSheet } from '@/features/settings/ConnectAssistantSheet.js';
import { settingsPath } from '@/features/settings/paths.js';
import { deviceLabel, hubRows, type AssistantTab, type HubRow } from './hub.js';
import { refreshSurfaces } from './state.js';
import styles from './Everywhere.module.css';

type Fetch = 'loading' | 'fresh' | 'offline' | 'failed';

/** The status line under a row's name. */
function statusOf(row: HubRow): string | undefined {
  switch (row.status) {
    case 'here':
      return t('everywhere.here');
    case 'connected':
      if (row.id === 'kindle_import' && row.count !== undefined)
        return t('everywhere.kindleCount', { count: row.count });
      return row.lastUsedAt === undefined
        ? t('everywhere.connected')
        : t('everywhere.connectedWhen', { when: lastSeenLabel(row.lastUsedAt) });
    case 'notYet':
      return t('everywhere.notYet');
    case 'notHere':
      if (row.action.kind === 'none' && row.action.note !== undefined) return t(row.action.note);
      return row.id === 'desktop' ? t('everywhere.macWindows') : t('everywhere.onComputer');
    case 'coming':
      return row.id === 'ios' ? t('everywhere.comingLater') : t('everywhere.comingSoon');
    case 'unknown':
      return undefined;
  }
}

/**
 * "Lexpad everywhere": every place the notebook can be, what this account
 * already uses, and the one honest next step from this device for each of
 * the rest. Pull, not push: it is always here, whatever was dismissed on
 * Today.
 *
 * The statuses come from the server (only it knows what was used on other
 * devices) and are drawn from the copy in IndexedDB first, then read again
 * when the page opens and when the app comes back to the front, so a
 * connection made in another app shows up by itself.
 */
export function Everywhere({
  say,
}: {
  say: (message: string, isError?: boolean) => void;
}): React.JSX.Element {
  const navigate = useNavigate();
  const device = useMemo(() => currentDevice(), []);
  const cached = useLiveQuery(() => getMeta('surfaces'), null, []);
  const [fetch, setFetch] = useState<Fetch>('loading');
  const [assistant, setAssistant] = useState<AssistantTab | undefined>();
  const live = useRef(true);

  const load = useCallback((): void => {
    refreshSurfaces()
      .then(() => {
        if (live.current) setFetch('fresh');
      })
      .catch((cause: unknown) => {
        if (live.current) setFetch(isApiError(cause, 'offline') ? 'offline' : 'failed');
      });
  }, []);

  useEffect(() => {
    live.current = true;
    load();
    const onVisible = (): void => {
      if (document.visibilityState === 'visible') load();
    };
    document.addEventListener('visibilitychange', onVisible);
    const offResume = platform.lifecycle.onResume(load);
    return () => {
      live.current = false;
      document.removeEventListener('visibilitychange', onVisible);
      offResume();
    };
  }, [load]);

  const rows = hubRows(device, cached?.list);

  const send = (url: string): void => {
    platform.share
      .link(url, t('everywhere.title'))
      .then((how) => {
        if (how === 'copied') say(t('everywhere.linkCopied'));
      })
      .catch(() => {
        say(t('error.generic'), true);
      });
  };

  return (
    <>
      <div className={styles.group}>
        {rows.map((row) => {
          const status = statusOf(row);
          const name = row.id === 'device' ? t(deviceLabel(device)) : t(`everywhere.row.${row.id}`);
          return (
            <div key={row.id} className={styles.row}>
              <span className={styles.text}>
                <span className={styles.name}>
                  {name}
                  {row.beta && <span className={styles.beta}>{t('everywhere.beta')}</span>}
                </span>
                {status !== undefined && (
                  <span
                    className={cx(
                      styles.status,
                      (row.status === 'connected' || row.status === 'here') && styles.statusOn,
                    )}
                  >
                    {status}
                  </span>
                )}
              </span>
              {row.action.kind === 'link' && (
                <a className={styles.action} href={row.action.href} target="_blank" rel="noopener noreferrer">
                  {t(row.action.label)}
                </a>
              )}
              {row.action.kind === 'send' && (
                <button
                  type="button"
                  className={styles.action}
                  onClick={() => {
                    if (row.action.kind === 'send') send(row.action.url);
                  }}
                >
                  {t(row.action.label)}
                </button>
              )}
              {row.action.kind === 'assistant' && (
                <button
                  type="button"
                  className={styles.action}
                  onClick={() => {
                    if (row.action.kind === 'assistant') setAssistant(row.action.tab);
                  }}
                >
                  {t(row.action.label)}
                </button>
              )}
              {row.action.kind === 'import' && (
                <button
                  type="button"
                  className={styles.action}
                  onClick={() => {
                    void navigate(settingsPath('data'));
                  }}
                >
                  {t(row.action.label)}
                </button>
              )}
            </div>
          );
        })}
      </div>
      {fetch === 'loading' && cached === null && (
        <p className="sr-only" role="status">
          {t('everywhere.loading')}
        </p>
      )}
      {(fetch === 'offline' || fetch === 'failed') && (
        <p className={styles.note} role="status">
          {cached !== null
            ? t('everywhere.asOf', { date: lastSeenLabel(cached.at) })
            : fetch === 'offline'
              ? t('everywhere.offline')
              : t('everywhere.failed')}
        </p>
      )}
      {assistant !== undefined && (
        <ConnectAssistantSheet
          say={say}
          initial={assistant}
          onClose={() => {
            setAssistant(undefined);
            load();
          }}
        />
      )}
    </>
  );
}
