/**
 * Changing a notebook's schedule settings. Like creating a notebook, this is
 * one of the few writes that goes to the server rather than the outbox: the
 * server stores it, records it for the account's other devices and is the
 * one that applies it to every answer. It needs a connection.
 */
import { ApiError } from '@/api/errors.js';
import { notebooks } from '@/api/endpoints.js';
import type { ApiNotebookScheduleUpdate } from '@/api/types.js';
import { db, type LexpadDb, type StoredSchedule } from '@/db/schema.js';
import { platform } from '@/lib/platform/index.js';
import { scheduleFromApi } from '@/sync/mapping.js';
import { useSync } from '@/sync/store.js';

/**
 * Saves a change and keeps the server's answer locally. Answers still
 * waiting to be sent go first, so the server judges them by the settings
 * they were given under; a failure there is not a reason to refuse the
 * change, and the push simply happens later.
 */
export async function saveSchedule(
  notebookId: string,
  change: ApiNotebookScheduleUpdate,
  database: LexpadDb = db,
): Promise<StoredSchedule> {
  if (!platform.network.online) throw new ApiError('offline', 'offline');
  await useSync
    .getState()
    .syncNow()
    .catch(() => undefined);
  const saved = await notebooks.putSchedule(notebookId, change);
  const stored = scheduleFromApi(saved.schedule);
  await database.schedules.put(stored);
  return stored;
}
