const DEVICE_NAMES: Record<ApiOlderDevice['platform'], MessageKey> = {
  android: 'schedule.device.android',
  ios: 'schedule.device.ios',
  desktop: 'schedule.device.desktop',
  web: 'schedule.device.web',
};

/** One choice in a group of rows: its name, what it does, and an optional mark. */
interface ChoiceOption<T extends string> {
  value: T;
  label: MessageKey;
  note: MessageKey;
  badge?: MessageKey;
}

const AFTER_MISS: readonly ChoiceOption<AfterMiss>[] = [
  { value: 'restart', label: 'schedule.restart', note: 'schedule.restartNote' },
  { value: 'back2', label: 'schedule.back2', note: 'schedule.back2Note' },
];

/**
 * Smart carries a Beta mark while the replay of real answers (gate G0) has
 * not shown it to be better on Lexpad's own data; it stays a choice, never a
 * default, until then.
 */
const SCHEDULERS: readonly ChoiceOption<Scheduler>[] = [
  { value: 'boxes', label: 'schedule.boxes', note: 'schedule.boxesNote' },
  { value: 'smart', label: 'schedule.smart', note: 'schedule.smartNote', badge: 'schedule.beta' },
];

/**
 * The same two with Boxes marked as the one to keep while Smart is Beta
 * (the new learner's journey, §5.1): two plain choices, nothing that says
 * "try it" to somebody who has not used either yet.
 */
const SCHEDULERS_LEARN: readonly ChoiceOption<Scheduler>[] = [
  { value: 'boxes', label: 'schedule.boxes', note: 'schedule.boxesNote', badge: 'schedule.recommended' },
  { value: 'smart', label: 'schedule.smart', note: 'schedule.smartNote', badge: 'schedule.beta' },
];

/** The parts of the page another screen may open it at that sit under "More options". */
const FOLDED_FOCUS: readonly string[] = [`#${SCHEDULE_FOCUS.limits}`, `#${SCHEDULE_FOCUS.hardWords}`];

/** The retention choices: the three presets and a custom target. */
type Preset = keyof RetentionPresets | 'custom';

const PRESETS: readonly { value: Preset; label: MessageKey }[] = [
  { value: 'relaxed', label: 'schedule.relaxed' },
  { value: 'balanced', label: 'schedule.balanced' },
  { value: 'exam', label: 'schedule.exam' },
  { value: 'custom', label: 'schedule.custom' },
];

/**
 * How long the custom slider waits after the last move before it saves: a
 * drag across the range is one change on the server, not eighteen. A
 * feel-of-the-control choice, not a value the server could hold.
 */
const CUSTOM_SAVE_DELAY_MS = 600;

/**
 * How words come back (SRS v2): one learner's schedule settings for the
 * notebook being shown. Reads from IndexedDB like every page; a change goes
 * to the server at once, because the server applies the settings to every
 * answer and tells the account's other devices. So it needs a connection,
 * and offline the controls rest with a reason while the schedule keeps
 * working. While a change is saving, the control shows the new value; if it
 * fails, the stored one comes back and the page says nothing changed.
 *
 * Phase C adds the scheduler itself (Boxes or Smart, Smart marked Beta) and
 * Smart's target. Switching to Smart asks first, because it changes how
 * every later answer is scheduled; nothing visible moves on the day, which
 * the sheet says. Switching back acts at once and offers Undo.
 */
export function ScheduleSettings(): React.JSX.Element {
  const data = useLiveQuery(loadSchedulePage, SCHEDULE_LOADING, []);
  const online = useOnline();
  const { status, failed, say } = useSay();
  /**
   * The change being saved, shown at once. Once saved it stays on screen
   * until the local copy has caught up with the server's stamp (`until`),
   * so the control never flicks back to the old value for a frame; any
   * later change, from here or another device, is newer and wins.
   */
  const [pending, setPending] = useState<{ update: ApiNotebookScheduleUpdate; until?: string } | undefined>(
    undefined,
  );
  const [confirmSmart, setConfirmSmart] = useState(false);
  const [toast, setToast] = useState<{ message: string; undo?: () => void } | undefined>(undefined);
  const saving = pending !== undefined && pending.until === undefined;
  // Opening this page is asking for this notebook's numbers: read them again.
  const stats = useSrsStats(shows(data.srs, 'trueRetention') || shows(data.srs, 'tuning'), true);

  // The flag decides what this page may show; a stale copy is read again
  // when the page opens, not only on the sync's own clock.
  useEffect(() => {
    void refreshSrs({ force: true }).catch(() => undefined);
  }, []);

  // Opened at a part of the page: once it is drawn, bring it into view and
  // put the focus on the control it is about, once a visit. Focus only:
  // choosing is still the learner's.
  const { hash } = useLocation();
  const focused = useRef(false);
  const drawn = data.ready && data.srs.enabled && data.schedule !== undefined;
  useEffect(() => {
    if (!drawn || focused.current) return;
    const target =
      hash === `#${SCHEDULE_FOCUS.smart}`
        ? document.querySelector<HTMLElement>(`#${SCHEDULE_FOCUS.smart} [data-value="smart"]`)
        : hash === `#${SCHEDULE_FOCUS.limits}`
          ? document.querySelector<HTMLElement>(`#${SCHEDULE_FOCUS.limits} select`)
          : hash === `#${SCHEDULE_FOCUS.hardWords}`
            ? document.querySelector<HTMLElement>(`#${SCHEDULE_FOCUS.hardWords} select`)
            : null;
    if (target === null) return;
    focused.current = true;
    target.dataset.landed = 'true';
    target.scrollIntoView({ block: 'center' });
    target.focus({ preventScroll: true });
  }, [drawn, hash]);

  // The new learner's journey: the Smart card waits for the history Smart
  // needs, as Today's invitation does (C4); read only while it could show.
  const learnOn = learnShows(data.srs);
  const notebookId = data.notebook?.id;
  const introCould =
    learnOn && !data.smartIntroSeen && data.schedule !== undefined && data.schedule.scheduler !== 'smart';
  const smartReady = useLiveQuery<boolean>(
    async () => (notebookId !== undefined && introCould ? smartHistoryReady(notebookId, localDay()) : false),
    false,
    [notebookId, introCould],
  );
  // "More options" as the learner left it, until they open or close it here.
  const [moreOverride, setMoreOverride] = useState<boolean | undefined>(undefined);

  if (!data.ready) {
    return (
      <SubPage title={t('schedule.title')}>
        <Skeleton lines={5} />
        <span className="sr-only" role="status">
          {t('state.loading')}
        </span>
      </SubPage>
    );
  }

  const { notebook, schedule, srs } = data;
  if (!srs.enabled) {
    return (
      <SubPage title={t('schedule.title')}>
        <EmptyState
          compact
          icon="info"
          tone="quiet"
          title={t('schedule.unavailable')}
          body={t('schedule.unavailableBody')}
        />
      </SubPage>
    );
  }
  if (notebook === undefined || schedule === undefined) {
    return (
      <SubPage title={t('schedule.title')}>
        <EmptyState
          compact
          icon="notebook"
          title={t('schedule.noNotebook')}
          body={t('schedule.noNotebookBody')}
        />
      </SubPage>
    );
  }

  const storedAt = data.saved?.updatedAt;
  const showPending =
    pending !== undefined &&
    (pending.until === undefined ||
      storedAt === undefined ||
      Date.parse(storedAt) < Date.parse(pending.until));
  const shown = { ...schedule, ...(showPending ? pending.update : {}) };
  const locked = !online || saving;
  const tuningOn = shown.tuning ?? data.saved?.tuning ?? true;
  const offersSmart = shows(srs, 'smart');
  const smart = shown.scheduler === 'smart';

  const change = async (update: ApiNotebookScheduleUpdate): Promise<boolean> => {
    if (locked) return false;
    setPending({ update });
    say(t('schedule.saving'));
    try {
      const stored = await saveSchedule(notebook.id, update);
      setPending({ update, until: stored.updatedAt ?? new Date(0).toISOString() });
      say(t('schedule.saved'));
      return true;
    } catch (error) {
      setPending(undefined);
      say(isApiError(error, 'offline') ? t('schedule.offline') : t('schedule.error'), true);
      return false;
    }
  };

  const toSmart = async (): Promise<void> => {
    setConfirmSmart(false);
    if (await change({ scheduler: 'smart' })) {
      setToast({ message: t('schedule.nowSmart', { notebook: notebook.title }) });
    }
  };
  const toBoxes = async (): Promise<void> => {
    if (await change({ scheduler: 'boxes' })) {
      setToast({
        message: t('schedule.nowBoxes', { notebook: notebook.title }),
        // Back to Smart is the change the learner already confirmed once.
        undo: () => {
          void change({ scheduler: 'smart' });
        },
      });
    }
  };

  // One notice per kind of app, newest first, however many of each there are.
  const older = [...new Set(srs.olderDevices.map((device) => device.platform))];

  // Smart's own card, under its target: the switch names it, so no heading repeats it.
  const tuningSection = offersSmart && smart && shows(srs, 'tuning') && (
    <Section>
      <div className={styles.group}>
        <SwitchRow
          label={t('schedule.tuning')}
          checked={tuningOn}
          disabled={locked}
          onChange={(on) => {
            void change({ tuning: on });
          }}
        />
        <p className={styles.groupNote}>{t('schedule.tuningNote')}</p>
        <p className={own.tuningState} role="status">
          {tuningLine(tuningOn, data.saved, statsFor(stats.stored, [notebook.id])[0]?.tuning)}
        </p>
      </div>
    </Section>
  );

  const answersSection = ((shows(srs, 'afterMiss') && !smart) || shows(srs, 'practiceOnly')) && (
    <Section title={t('schedule.answers')}>
      <div className={styles.group}>
        {shows(srs, 'afterMiss') && !smart && (
          <>
            <ChoiceRows
              label={t('schedule.afterMiss')}
              options={AFTER_MISS}
              value={shown.afterMiss}
              disabled={locked}
              onChange={(afterMiss) => {
                void change({ afterMiss });
              }}
            />
            <p className={styles.groupNote}>{t('schedule.afterMissNote')}</p>
          </>
        )}
        {shows(srs, 'practiceOnly') && (
          <>
            <SwitchRow
              label={t('schedule.extraPractice')}
              checked={shown.extraPractice === 'keep'}
              disabled={locked}
              onChange={(keep) => {
                void change({ extraPractice: keep ? 'keep' : 'moves' });
              }}
            />
            <p className={styles.groupNote}>{t('schedule.extraPracticeNote')}</p>
          </>
        )}
      </div>
    </Section>
  );

  const capLabel = (cap: number): string =>
    cap === 0 ? t('schedule.reviewCapOff') : t('schedule.reviewCapValue', { count: cap });
  const leechLabel = (count: number): string =>
    count === 0 ? t('schedule.leechOff') : t('schedule.leechValue', { count });

  const limitsSection = shows(srs, 'reviewCap') && (
    <Section title={t('schedule.limits')} id={SCHEDULE_FOCUS.limits}>
      <div className={styles.group}>
        <PickerRow
          label={t('schedule.reviewCap')}
          value={shown.reviewCap}
          disabled={locked}
          options={[0, ...srs.choices.reviewCap.filter((cap) => cap > 0)].map((cap) => ({
            value: cap,
            label: capLabel(cap),
          }))}
          onChange={(reviewCap) => {
            void change({ reviewCap });
          }}
        />
        <p className={styles.groupNote}>{t('schedule.reviewCapNote')}</p>
      </div>
    </Section>
  );

  const hardSection = shows(srs, 'leech') && (
    <Section title={t('schedule.hardWords')} id={SCHEDULE_FOCUS.hardWords}>
      <div className={styles.group}>
        <PickerRow
          label={t('schedule.leech')}
          value={shown.leechThreshold}
          disabled={locked}
          options={srs.choices.leechThreshold.map((count) => ({ value: count, label: leechLabel(count) }))}
          onChange={(count) => {
            // Only the server's own choices are offered, and it checks them again.
            void change({
              leechThreshold: count as NonNullable<ApiNotebookScheduleUpdate['leechThreshold']>,
            });
          }}
        />
        <p className={styles.groupNote}>{t('schedule.leechNote')}</p>
      </div>
    </Section>
  );

  // With the new learner's journey, the last 30 days appear once there are numbers to show.
  const hasNumbers = (statsFor(stats.stored, [notebook.id])[0]?.reviews ?? 0) > 0;
  const statsSection = shows(srs, 'trueRetention') && (!learnOn || hasNumbers) && (
    <Section title={t('schedule.statsTitle', { days: SRS_STATS_DAYS })}>
      <NotebookStats stored={stats.stored} ready={stats.ready} fetch={stats.fetch} notebookId={notebook.id} />
    </Section>
  );

  const olderBlock = older.length > 0 && (
    <div className={own.older}>
      {older.map((device) => (
        <p key={device} className={own.olderLine}>
          <Icon name="computer" size={16} weight={2} className={own.bannerIcon} />
          <span>{t('schedule.olderDevice', { device: t(DEVICE_NAMES[device]) })}</span>
        </p>
      ))}
    </div>
  );

  // "More options" (the new learner's journey, §5.1): what differs from the
  // notebook's defaults is named on the row and opens it, as does a link to
  // a control inside and having left it open here last time.
  const defaults = data.defaults;
  const changed =
    defaults === undefined
      ? []
      : [
          shows(srs, 'afterMiss') && !smart && shown.afterMiss !== defaults.afterMiss
            ? t('settings.changedItem', {
                name: t('schedule.afterMiss'),
                value: t(shown.afterMiss === 'back2' ? 'schedule.back2' : 'schedule.restart'),
              })
            : undefined,
          shows(srs, 'practiceOnly') && shown.extraPractice !== defaults.extraPractice
            ? t('settings.changedItem', {
                name: t('schedule.extraPractice'),
                value: t(shown.extraPractice === 'keep' ? 'schedule.on' : 'schedule.off'),
              })
            : undefined,
          shows(srs, 'reviewCap') && shown.reviewCap !== 0
            ? t('settings.changedItem', { name: t('schedule.reviewCap'), value: capLabel(shown.reviewCap) })
            : undefined,
          shows(srs, 'leech') && shown.leechThreshold !== defaults.leechThreshold
            ? t('settings.changedItem', {
                name: t('schedule.leech'),
                value: leechLabel(shown.leechThreshold),
              })
            : undefined,
          offersSmart && smart && shows(srs, 'tuning') && !tuningOn
            ? t('settings.changedItem', { name: t('schedule.tuning'), value: t('schedule.off') })
            : undefined,
        ].filter((item) => item !== undefined);
  const folded = [answersSection, limitsSection, hardSection, tuningSection, olderBlock].some(
    (part) => part !== false,
  );
  const moreOpen = moreOverride ?? (changed.length > 0 || FOLDED_FOCUS.includes(hash) || data.moreOpen);

  return (
    <SubPage title={t('schedule.title')}>
      <div className={own.leadBlock}>
        <p className={own.lead}>{t(smart ? 'schedule.leadSmart' : 'schedule.lead')}</p>
        {learnOn && (
          <Link to={settingsPath('how')} className={own.howLink}>
            {t('schedule.howLink')}
            <Icon name="chevronRight" size={14} weight={2.2} className={own.howGo} />
          </Link>
        )}
      </div>

      <div className={own.forNotebook}>
        <NotebookChip />
        <p className={own.notebookNote}>{t('schedule.forNotebook', { notebook: notebook.title })}</p>
      </div>

      {!online && (
        <p className={own.banner} role="status">
          <Icon name="info" size={16} weight={2} className={own.bannerIcon} />
          <span>{t('schedule.offline')}</span>
        </p>
      )}

      {offersSmart && (
        <Section title={t('schedule.scheduler')} id={SCHEDULE_FOCUS.smart}>
          {!data.smartIntroSeen && !smart && (!learnOn || smartReady) && (
            <div className={own.intro}>
              <p className={own.introText}>
                <span className={own.introTitle}>{t('schedule.introTitle')}</span>
                <span className={own.introBody}>{t('schedule.introBody')}</span>
              </p>
              <button
                type="button"
                className={own.introDismiss}
                onClick={() => {
                  void setMeta('smartIntroSeen', true);
                }}
              >
                {t('schedule.introDismiss')}
              </button>
            </div>
          )}
          <div className={styles.group}>
            <ChoiceRows
              label={t('schedule.scheduler')}
              hideLabel
              options={learnOn ? SCHEDULERS_LEARN : SCHEDULERS}
              value={shown.scheduler}
              disabled={locked}
              onChange={(scheduler) => {
                if (scheduler === 'smart') setConfirmSmart(true);
                else void toBoxes();
              }}
            />
            <p className={styles.groupNote}>{t('schedule.betaNote')}</p>
          </div>
        </Section>
      )}

      {offersSmart && smart && (
        <Section title={t('schedule.remember')}>
          <div className={styles.group}>
            <RetentionChoice
              value={shown.retention}
              presets={srs.choices.retention}
              disabled={locked}
              onChange={(retention) => {
                void change({ retention });
              }}
            />
          </div>
        </Section>
      )}

      {learnOn ? (
        <>
          {statsSection}
          {folded && (
            <MoreOptions
              summary={t(smart ? 'schedule.moreSummarySmart' : 'schedule.moreSummary')}
              changed={changed}
              open={moreOpen}
              onToggle={(open) => {
                setMoreOverride(open);
                void rememberMoreOptions('schedule', open);
              }}
            >
              {answersSection}
              {limitsSection}
              {hardSection}
              {tuningSection}
              {olderBlock}
            </MoreOptions>
          )}
        </>
      ) : (
        <>
          {tuningSection}
          {answersSection}
          {limitsSection}
          {hardSection}
          {statsSection}
          {olderBlock}
        </>
      )}
      <StatusLine status={status} failed={failed} />

      {confirmSmart && (
        <Confirm
          title={t('schedule.switchTitle', { notebook: notebook.title })}
          body={[t('schedule.switchKeep'), t('schedule.switchGap'), t('schedule.switchBack')]}
          confirmLabel={t('schedule.switchConfirm')}
          cancelLabel={t('schedule.switchNotNow')}
          onConfirm={() => {
            void toSmart();
          }}
          onCancel={() => {
            setConfirmSmart(false);
          }}
        />
      )}
      {toast !== undefined && (
        <Toast
          message={toast.message}
          onUndo={toast.undo}
          onDone={() => {
            setToast(undefined);
          }}
        />
      )}
    </SubPage>
  );
}

/**
 * A choice of a few rows, each with a line saying what it does: after a
 * miss, and the scheduler. A radio group with its own arrow keys, so a
 * keyboard moves between the rows the way it moves through any set of
 * radios, and each option's description is read with it. Arrows move the
 * focus and choose, as radios do; a choice that asks first (Smart) asks
 * from the arrow too.
 */
function ChoiceRows<T extends string>({
  label,
  hideLabel = false,
  options,
  value,
  disabled,
  onChange,
}: {
  label: string;
  hideLabel?: boolean;
  options: readonly ChoiceOption<T>[];
  value: T;
  disabled: boolean;
  onChange: (value: T) => void;
}): React.JSX.Element {
  const id = useId();
  const refs = useRef<(HTMLButtonElement | null)[]>([]);
  const move = (from: number, step: number): void => {
    const next = (from + step + options.length) % options.length;
    const option = options[next];
    if (option === undefined) return;
    refs.current[next]?.focus();
    onChange(option.value);
  };

  return (
    <div className={own.radios} role="radiogroup" aria-labelledby={`${id}-label`}>
      <p id={`${id}-label`} className={hideLabel ? 'sr-only' : own.radiosLabel}>
        {label}
      </p>
      {options.map((option, index) => {
        const on = option.value === value;
        return (
          <button
            key={option.value}
            ref={(element) => {
              refs.current[index] = element;
            }}
            type="button"
            role="radio"
            aria-checked={on}
            data-value={option.value}
            aria-labelledby={`${id}-${option.value}-label`}
            aria-describedby={`${id}-${option.value}`}
            tabIndex={on ? 0 : -1}
            disabled={disabled}
            className={cx(styles.row, styles.button, own.radio, on && own.radioOn)}
            onClick={() => {
              if (!on) onChange(option.value);
            }}
            onKeyDown={(event) => {
              if (event.key === 'ArrowDown' || event.key === 'ArrowRight') {
                event.preventDefault();
                move(index, 1);
              } else if (event.key === 'ArrowUp' || event.key === 'ArrowLeft') {
                event.preventDefault();
                move(index, -1);
              }
            }}
          >
            <span className={own.radioMark} aria-hidden="true">
              {on && <span className={own.radioDot} />}
            </span>
            <span className={own.radioText}>
              <span id={`${id}-${option.value}-label`} className={cx(styles.label, own.radioName)}>
                {t(option.label)}
                {option.badge !== undefined && <span className={own.badge}>{t(option.badge)}</span>}
              </span>
              <span id={`${id}-${option.value}`} className={own.radioNote}>
                {t(option.note)}
              </span>
            </span>
          </button>
        );
      })}
    </div>
  );
}

/**
 * Smart's target: Relaxed, Balanced, Exam or a custom value. A single-choice
 * segmented control (a radio group with arrow keys), a line saying what the
 * choice means, and for Custom a slider from 80 to 97 that saves once the
 * learner stops moving it.
 */
function RetentionChoice({
  value,
  presets,
  disabled,
  onChange,
}: {
  value: number;
  presets: RetentionPresets;
  disabled: boolean;
  onChange: (value: number) => void;
}): React.JSX.Element {
  const id = useId();
  const refs = useRef<(HTMLButtonElement | null)[]>([]);
  const named = (Object.keys(presets) as (keyof RetentionPresets)[]).find((key) => presets[key] === value);
  const [customOpen, setCustomOpen] = useState(named === undefined);
  const [draft, setDraft] = useState(value);
  const timer = useRef<number | undefined>(undefined);
  const selected: Preset = customOpen || named === undefined ? 'custom' : named;

  // The stored value is the truth whenever the slider is not being moved.
  useEffect(() => {
    if (timer.current === undefined) setDraft(value);
  }, [value]);
  useEffect(
    () => () => {
      window.clearTimeout(timer.current);
    },
    [],
  );

  const pick = (preset: Preset): void => {
    if (preset === 'custom') {
      setCustomOpen(true);
      return;
    }
    setCustomOpen(false);
    if (presets[preset] !== value) onChange(presets[preset]);
  };
  const move = (from: number, step: number): void => {
    const next = (from + step + PRESETS.length) % PRESETS.length;
    const option = PRESETS[next];
    if (option === undefined) return;
    refs.current[next]?.focus();
    pick(option.value);
  };
  const slide = (next: number): void => {
    setDraft(next);
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => {
      timer.current = undefined;
      if (next !== value) onChange(next);
    }, CUSTOM_SAVE_DELAY_MS);
  };

  const note =
    selected === 'custom'
      ? t('schedule.customNote')
      : t(`schedule.${selected}Note`, { percent: presets[selected] });

  return (
    <div className={own.retention}>
      <div
        className={own.presets}
        role="radiogroup"
        aria-label={t('schedule.remember')}
        aria-describedby={`${id}-note`}
      >
        {PRESETS.map((option, index) => {
          const on = option.value === selected;
          return (
            <button
              key={option.value}
              ref={(element) => {
                refs.current[index] = element;
              }}
              type="button"
              role="radio"
              aria-checked={on}
              tabIndex={on ? 0 : -1}
              disabled={disabled}
              className={cx(own.preset, on && own.presetOn)}
              onClick={() => {
                pick(option.value);
              }}
              onKeyDown={(event) => {
                if (event.key === 'ArrowRight' || event.key === 'ArrowDown') {
                  event.preventDefault();
                  move(index, 1);
                } else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') {
                  event.preventDefault();
                  move(index, -1);
                }
              }}
            >
              {t(option.label)}
            </button>
          );
        })}
      </div>
      <p id={`${id}-note`} className={own.presetNote}>
        {note}
      </p>
      {selected === 'custom' && (
        <div className={own.custom}>
          <span className={styles.sliderHead}>
            <label htmlFor={`${id}-slider`} className={styles.label}>
              {t('schedule.customLabel')}
            </label>
            <span className={styles.sliderValue} aria-hidden="true">
              {t('schedule.percent', { percent: draft })}
            </span>
          </span>
          <input
            id={`${id}-slider`}
            type="range"
            className={styles.slider}
            min={RETENTION_MIN}
            max={RETENTION_MAX}
            step={1}
            value={draft}
            disabled={disabled}
            aria-valuetext={t('schedule.percentSpoken', { percent: draft })}
            onChange={(event) => {
              slide(Number(event.target.value));
            }}
          />
        </div>
      )}
    </div>
  );
}

/** A labelled choice from a short list of numbers, as a native select. */
function PickerRow({
  label,
  value,
  options,
  disabled,
  onChange,
}: {
  label: string;
  value: number;
  options: readonly { value: number; label: string }[];
  disabled: boolean;
  onChange: (value: number) => void;
}): React.JSX.Element {
  // A value the flag no longer offers is still shown as what it is.
  const all = options.some((option) => option.value === value)
    ? options
    : [...options, { value, label: String(value) }];
  return (
    // Under its label at full width on a phone, beside it from medium up:
    // "Ask after 6 misses" ran past the card's edge at 390 (access proposal 5).
    <div className={cx(styles.row, styles.rowStatic, styles.rowStacked, own.pickerRow)}>
      <span className={styles.label}>{label}</span>
      <select
        className={styles.select}
        aria-label={label}
        value={value}
        disabled={disabled}
        onChange={(event) => {
          onChange(Number(event.target.value));
        }}
      >
        {all.map((option) => (
          <option key={option.value} value={option.value}>
            {option.label}
          </option>
        ))}
      </select>
    </div>
  );
}

/** What personal tuning last did for this notebook, in one sentence. */
function tuningLine(
  on: boolean,
  saved: StoredSchedule | undefined,
  status: { state: 'waiting' | 'tuned' | 'kept' | 'failed'; lastRunAt?: string } | undefined,
): string {
  if (!on) return t('schedule.tuningOff');
  const lines: string[] = [];
  const tunedAt = saved?.params?.source === 'tuned' ? saved.params.tunedAt : undefined;
  if (tunedAt !== undefined) {
    lines.push(
      t('schedule.tuningTuned', { date: lastSeenLabel(tunedAt), count: saved?.params?.reviews ?? 0 }),
    );
  }
  if (status?.state === 'failed') lines.push(t('schedule.tuningFailed'));
  else if (status?.state === 'kept' && tunedAt === undefined && status.lastRunAt !== undefined) {
    lines.push(t('schedule.tuningKept', { date: lastSeenLabel(status.lastRunAt) }));
  }
  if (lines.length === 0) lines.push(t('schedule.tuningWaiting'));
  return lines.join(' ');
}

/**
 * This notebook's last 30 days: the share of due words remembered and the
 * reviews a day, from the server's copy (every device's answers), with "as
 * of" when it could not be read again and its own words when it never was.
 */
function NotebookStats({
  stored,
  ready,
  fetch,
  notebookId,
}: {
  stored: StoredSrsStats | null;
  ready: boolean;
  fetch: StatsFetch;
  notebookId: string;
}): React.JSX.Element {
  if (!ready || (stored === null && fetch === 'idle')) {
    return (
      <div className={own.stats}>
        <Skeleton lines={1} />
        <span className="sr-only" role="status">
          {t('state.loading')}
        </span>
      </div>
    );
  }
  if (stored === null) {
    return (
      <p className={own.statsQuiet}>
        {fetch === 'offline' ? t('schedule.statsOffline') : t('schedule.statsFailed')}
      </p>
    );
  }
  const share = retentionFor(stored, [notebookId]);
  const reviews = statsFor(stored, [notebookId])[0]?.reviews ?? 0;
  const perDay = Math.round(reviews / Math.max(1, stored.stats.days));
  const stale = fetch === 'offline' || fetch === 'failed';
  return (
    <div className={own.statsWrap}>
      <dl className={own.stats}>
        <div className={own.stat}>
          <dt className={own.statLabel}>{t('schedule.statsRemembered')}</dt>
          <dd className={share.percent === null ? own.statQuiet : own.statValue}>
            {share.percent === null
              ? t('schedule.statsNotEnough')
              : t('retention.percent', { percent: share.percent })}
          </dd>
        </div>
        <div className={own.stat}>
          <dt className={own.statLabel}>{t('schedule.statsPerDay')}</dt>
          <dd className={own.statValue}>{perDay}</dd>
        </div>
      </dl>
      {stale && (
        <p className={own.statsAsOf}>
          {t(fetch === 'offline' ? 'schedule.statsAsOfOffline' : 'schedule.statsAsOf', {
            when: relativeTimeInline(stored.at),
          })}
        </p>
      )}
    </div>
  );
}
