import type { Settings } from '@lexpad/core';
import { patchSettings } from '@/db/mutations.js';
import { syncSoon } from '@/sync/store.js';

/**
 * Writes a settings change through the same mutation path as any other
 * edit, so a change made offline is queued and reaches the server with the
 * rest. Every write asks for a sync straight away, as the other screens do;
 * a change that only reached the server on the next timer looked lost.
 */
export function saveSettings(change: Partial<Settings>): void {
  void patchSettings(change).then(() => syncSoon());
}
