import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { NotebookSheet } from '@/features/notebook/NotebookSheet.js';
import { ShareSheet } from '@/features/share/ShareSheet.js';
import { SRS_OFF, loadSrsView } from '@/features/schedule/data.js';
import { LANGUAGE_NAMES, LOADING, loadSettingsScreen } from './data.js';
import { settingsPath } from './paths.js';
import { NavRow, Section, SubPage } from './SettingsKit.js';
import styles from './Settings.module.css';

/**
 * Notebooks: the way to every notebook (switch, add, merge, and which ones
 * a session draws from, all in the one sheet that owns them), then the
 * notebook on screen — its languages, its size and its share link.
 */
export function NotebookSettings(): React.JSX.Element {
  const navigate = useNavigate();
  const data = useLiveQuery(loadSettingsScreen, LOADING, []);
  const srs = useLiveQuery(loadSrsView, SRS_OFF, []);
  const { notebook, notebooks } = data;
  const [pickingNotebook, setPickingNotebook] = useState(false);
  const [sharing, setSharing] = useState(false);

  return (
    <SubPage title={t('settings.page.notebooks')}>
      <div className={styles.group}>
        {/* Always here, whatever the count: this is where somebody goes
            looking for their notebooks, and with one it is still the way
            to a second. */}
        <button
          type="button"
          className={cx(styles.row, styles.button)}
          disabled={notebook === undefined}
          onClick={() => {
            setPickingNotebook(true);
          }}
        >
          <span className={styles.label}>{t('settings.yourNotebooks')}</span>
          <span className={styles.value}>
            {notebooks.length > 1
              ? t('settings.notebooksCount', { count: notebooks.length })
              : notebook?.title}
          </span>
        </button>
      </div>

      <Section title={t('settings.thisNotebook')}>
        <div className={styles.group}>
          <button
            type="button"
            className={cx(styles.row, styles.button)}
            disabled={notebook === undefined}
            onClick={() => {
              void navigate('/welcome?edit=1');
            }}
          >
            <span className={styles.label}>{t('settings.languages')}</span>
            <span className={styles.value}>
              {t('settings.languagePair', {
                target: LANGUAGE_NAMES[notebook?.targetLang ?? 'en'],
                meaning: LANGUAGE_NAMES[notebook?.meaningLang ?? 'fa'],
              })}
            </span>
          </button>
          <div className={cx(styles.row, styles.rowStatic)}>
            <span className={styles.label}>{t('settings.words')}</span>
            <span className={styles.value}>{data.wordCount}</span>
          </div>
          {/* SRS v2: this learner's own schedule for the notebook. */}
          {srs.enabled && notebook !== undefined && (
            <NavRow to={settingsPath('schedule')} icon="progress" label={t('schedule.title')} />
          )}
          <button
            type="button"
            className={cx(styles.row, styles.button)}
            disabled={notebook === undefined}
            onClick={() => {
              setSharing(true);
            }}
          >
            <span className={styles.label}>{t('settings.share')}</span>
            <span className={styles.valueSmall}>{t('settings.shareNote')}</span>
          </button>
        </div>
      </Section>

      {pickingNotebook && (
        <NotebookSheet
          activeId={notebook?.id}
          onClose={() => {
            setPickingNotebook(false);
          }}
        />
      )}

      {sharing && notebook !== undefined && (
        <ShareSheet
          notebookId={notebook.id}
          onClose={() => {
            setSharing(false);
          }}
        />
      )}
    </SubPage>
  );
}
