/**
 * The install prompt. Android and desktop Chrome fire `beforeinstallprompt`,
 * which must be captured to be used later; iOS Safari fires nothing, so the
 * only thing to do there is tell the user where the button is.
 */
import { useEffect, useState } from 'react';
import { platform } from './platform/index.js';

/** A `beforeinstallprompt` event, which is not in the DOM typings. */
interface InstallPromptEvent extends Event {
  prompt: () => Promise<void>;
}

export interface InstallState {
  /** True once the browser has offered an install prompt to capture. */
  canPrompt: boolean;
  /** True on iOS Safari, where the user has to use the Share sheet. */
  iosHint: boolean;
  prompt: () => Promise<void>;
}

function isStandalone(): boolean {
  try {
    return window.matchMedia('(display-mode: standalone)').matches;
  } catch {
    return false;
  }
}

function isIosSafari(): boolean {
  const agent = navigator.userAgent;
  return /iPad|iPhone|iPod/.test(agent) && !/CriOS|FxiOS|EdgiOS/.test(agent);
}

export function useInstallPrompt(): InstallState {
  const [event, setEvent] = useState<InstallPromptEvent | undefined>(undefined);
  const [installed, setInstalled] = useState(() => isStandalone());

  useEffect(() => {
    // Inside a native shell the app is already installed.
    if (platform.env.embedded) return;

    const onPrompt = (raw: Event): void => {
      raw.preventDefault();
      setEvent(raw as InstallPromptEvent);
    };
    const onInstalled = (): void => {
      setInstalled(true);
      setEvent(undefined);
    };
    window.addEventListener('beforeinstallprompt', onPrompt);
    window.addEventListener('appinstalled', onInstalled);
    return () => {
      window.removeEventListener('beforeinstallprompt', onPrompt);
      window.removeEventListener('appinstalled', onInstalled);
    };
  }, []);

  const hidden = installed || platform.env.embedded;

  return {
    canPrompt: !hidden && event !== undefined,
    iosHint: !hidden && event === undefined && isIosSafari(),
    async prompt() {
      if (event === undefined) return;
      await event.prompt();
      setEvent(undefined);
    },
  };
}
