import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { useTheme, PALETTES, type Palette } from '@/lib/theme.js';
import { PALETTE_LABEL, THEMES } from './options.js';
import { saveSettings } from './save.js';
import { SubPage } from './SettingsKit.js';
import styles from './Settings.module.css';

const PALETTE_CLASS: Record<Palette, string | undefined> = {
  forest: styles.forest,
  coral: styles.coral,
};

/**
 * Appearance: the palette and the theme. Each is applied at once for the
 * next paint and saved like any other setting, so another device follows.
 * The controls sit on the main Settings page; the page of its own is kept
 * for links that name it.
 */
export function AppearanceSettings(): React.JSX.Element {
  return (
    <SubPage title={t('settings.page.appearance')}>
      <AppearanceControls />
    </SubPage>
  );
}

/** The palette and theme rows, shared by the main page and the Appearance page. */
export function AppearanceControls(): React.JSX.Element {
  const { theme, palette, setTheme, setPalette } = useTheme();

  return (
    <div className={styles.group}>
      <div className={cx(styles.row, styles.rowTall, styles.rowStatic)}>
        <span className={styles.label}>{t('settings.palette')}</span>
        <div className={styles.palettes} role="radiogroup" aria-label={t('settings.palette')}>
          {PALETTES.map((value) => (
            <button
              key={value}
              type="button"
              role="radio"
              aria-checked={value === palette}
              aria-label={t(PALETTE_LABEL[value])}
              className={cx(styles.palette, value === palette && styles.paletteOn)}
              onClick={() => {
                setPalette(value);
                saveSettings({ palette: value });
              }}
            >
              <span className={cx(styles.swatch, PALETTE_CLASS[value])} />
            </button>
          ))}
        </div>
      </div>
      <div className={cx(styles.row, styles.rowTall, styles.rowStatic)}>
        <span className={styles.label}>{t('settings.theme')}</span>
        <div className={styles.tray} role="radiogroup" aria-label={t('settings.theme')}>
          {THEMES.map((entry) => (
            <button
              key={entry.value}
              type="button"
              role="radio"
              aria-checked={entry.value === theme}
              className={cx(styles.trayButton, entry.value === theme && styles.trayOn)}
              onClick={() => {
                setTheme(entry.value);
                saveSettings({ theme: entry.value });
              }}
            >
              {t(entry.labelKey)}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}
