import { useEffect } from 'react';
import { useBilling } from '@/features/billing/state.js';

/**
 * The plan is the one thing Settings reads from the network rather than the
 * local database, so it is fetched when a page that shows it opens: the main
 * page, for the badge on the account card, and the Plan page itself.
 *
 * A purchase made in the Android app can finish while the app is closed,
 * and a reinstall or a new phone starts with no plan at all. Sending every
 * token Play still holds is what turns those back into the plan they paid
 * for; it does nothing anywhere but Android, and nothing when there is
 * nothing to send.
 */
export function usePlanOnOpen(): void {
  const refreshBilling = useBilling((state) => state.refresh);
  const restorePlay = useBilling((state) => state.restorePlayPurchases);
  useEffect(() => {
    void refreshBilling().then(() => restorePlay());
  }, [refreshBilling, restorePlay]);
}
