import { useCallback, useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { listNotebooks } from '@/db/repo.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { acceleratorOf, prettyShortcut } from '@/lib/desktopShortcut.js';
import { platform } from '@/lib/platform/index.js';
import type { DesktopSettings as Held, DesktopSettingsHost } from '@/lib/platform/types.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { settingsPath } from './paths.js';
import { Section, StatusLine, SubPage, SwitchRow } from './SettingsKit.js';
import { useSay } from './useSay.js';
import styles from './Settings.module.css';

/**
 * This computer: what only the desktop app has, in the same Settings as
 * everything else. The shortcut and the notebook it adds to, reading the
 * selection (macOS Accessibility, and what an update of the unsigned app
 * does to it), notifications on this computer, start-up, what leaves the
 * computer, and the version. Shown only inside the desktop app; every
 * change goes to the app's core, which holds these settings.
 */
export function DesktopSettings(): React.JSX.Element {
  const host = platform.desktop?.settings;
  if (host === undefined) {
    // Not the desktop app: there is nothing on this page for a browser or a phone.
    return (
      <SubPage title={t('settings.page.desktop')}>
        <p className={styles.dataNote}>{t('desktop.onlyInApp')}</p>
      </SubPage>
    );
  }
  return <DesktopPage host={host} />;
}

function DesktopPage({ host }: { host: DesktopSettingsHost }): React.JSX.Element {
  const [held, setHeld] = useState<Held | 'failed' | undefined>();
  const { status, failed, say } = useSay();
  const notebooks = useLiveQuery(listNotebooks, [], []);

  const reload = useCallback((): void => {
    host
      .read()
      .then(setHeld)
      .catch(() => {
        setHeld('failed');
      });
  }, [host]);
  // Read again when the window comes back: the learner may have just
  // allowed Accessibility or notifications in System Settings.
  useEffect(() => {
    reload();
    const again = (): void => {
      if (document.visibilityState === 'visible') reload();
    };
    document.addEventListener('visibilitychange', again);
    window.addEventListener('focus', reload);
    return () => {
      document.removeEventListener('visibilitychange', again);
      window.removeEventListener('focus', reload);
    };
  }, [reload]);

  if (held === undefined) return <SubPage title={t('settings.page.desktop')}>{null}</SubPage>;
  if (held === 'failed') {
    return (
      <SubPage title={t('settings.page.desktop')}>
        <p className={cx(styles.status, styles.statusError)} role="status">
          {t('desktop.readFailed')}
        </p>
      </SubPage>
    );
  }

  const mac = held.os === 'macos';
  const save = <T,>(work: Promise<T>, apply: (value: T) => Partial<Held>): void => {
    work
      .then((value) => {
        setHeld({ ...held, ...apply(value) });
      })
      .catch(() => {
        say(t('desktop.saveFailed'), true);
      });
  };
  const quickAdd =
    held.notebookId !== null && notebooks.some((n) => n.id === held.notebookId)
      ? held.notebookId
      : (notebooks[0]?.id ?? '');

  return (
    <SubPage title={t('settings.page.desktop')}>
      <p className={styles.dataNote}>{t('desktop.lead')}</p>

      <Section title={t('desktop.addTitle')}>
        <div className={styles.group}>
          <ShortcutRow
            shortcut={held.shortcut}
            mac={mac}
            onSave={(accelerator) =>
              host.setShortcut(accelerator).then((shortcut) => {
                setHeld({ ...held, shortcut });
              })
            }
          />
          {notebooks.length > 1 && (
            <div className={cx(styles.row, styles.rowStatic)}>
              <span className={styles.label}>{t('desktop.quickAddNotebook')}</span>
              <select
                className={styles.select}
                aria-label={t('desktop.quickAddNotebook')}
                value={quickAdd}
                onChange={(event) => {
                  const id = event.target.value;
                  save(host.setQuickAddNotebook(id), () => ({ notebookId: id }));
                }}
              >
                {notebooks.map((n) => (
                  <option key={n.id} value={n.id}>
                    {n.title}
                  </option>
                ))}
              </select>
            </div>
          )}
        </div>
        <p className={styles.dataNote}>
          {t('desktop.addNote', { keys: prettyShortcut(held.shortcut, mac) })}
        </p>
      </Section>

      <Section title={t('desktop.readingTitle')}>
        {held.accessibility === 'not_needed' ? (
          <p className={styles.dataNote}>{t('desktop.readingWindows')}</p>
        ) : (
          <>
            <div className={styles.group}>
              <div className={cx(styles.row, styles.rowStatic)}>
                <span className={styles.label}>{t('desktop.accessibility')}</span>
                <span className={styles.valueSmall}>
                  {held.accessibility === 'granted' ? t('desktop.allowed') : t('desktop.notAllowed')}
                </span>
              </div>
              <button
                type="button"
                className={cx(styles.row, styles.button)}
                onClick={() => {
                  host.openAccessibilitySettings().catch(() => {
                    say(t('desktop.saveFailed'), true);
                  });
                }}
              >
                <span className={styles.label}>{t('desktop.openSystemSettings')}</span>
              </button>
            </div>
            {held.accessibility === 'missing' && held.accessibilityStale && (
              <p className={cx(styles.status, styles.statusError)} role="status">
                {t('desktop.accessibilityStale')}
              </p>
            )}
            <p className={styles.dataNote}>{t('desktop.readingMac')}</p>
          </>
        )}
      </Section>

      <Section title={t('desktop.notificationsTitle')}>
        <div className={styles.group}>
          <SwitchRow
            label={t('desktop.notifications')}
            checked={held.notifications}
            onChange={(on) => {
              save(host.setNotifications(on), (access) => ({
                notifications: on,
                notificationAccess: on ? access : held.notificationAccess,
              }));
            }}
          />
          <Link to={settingsPath('notifications')} className={cx(styles.row, styles.button)}>
            <span className={styles.label}>{t('desktop.reminderTime')}</span>
          </Link>
        </div>
        {held.notifications && held.notificationAccess === 'denied' && (
          <>
            <p className={cx(styles.status, styles.statusError)} role="status">
              {mac ? t('desktop.notificationsDeniedMac') : t('desktop.notificationsDeniedWindows')}
            </p>
            <button
              type="button"
              className={styles.inlineButton}
              onClick={() => {
                host.openNotificationSettings().catch(() => {
                  say(t('desktop.saveFailed'), true);
                });
              }}
            >
              {mac ? t('desktop.openSystemSettings') : t('desktop.openWindowsSettings')}
            </button>
          </>
        )}
        <p className={styles.dataNote}>{t('desktop.notificationsNote')}</p>
      </Section>

      <Section title={t('desktop.startTitle')}>
        <div className={styles.group}>
          <SwitchRow
            label={t('desktop.startOnLogin')}
            checked={held.startOnLogin}
            onChange={(on) => {
              save(host.setStartOnLogin(on), (startOnLogin) => ({ startOnLogin }));
            }}
          />
          <SwitchRow
            label={t('desktop.openOnLaunch')}
            checked={held.openOnLaunch}
            onChange={(on) => {
              save(host.setOpenOnLaunch(on), (openOnLaunch) => ({ openOnLaunch }));
            }}
          />
          <SwitchRow
            label={t('desktop.openInBrowser')}
            checked={held.openInBrowser}
            onChange={(on) => {
              save(host.setOpenInBrowser(on), (openInBrowser) => ({ openInBrowser }));
            }}
          />
        </div>
        {held.developmentBuild && <p className={styles.dataNote}>{t('desktop.developmentBuild')}</p>}
      </Section>

      <Section title={t('desktop.privacyTitle')}>
        <ul className={styles.dataNote}>
          <li>{t('desktop.privacyLookUp')}</li>
          <li>{t('desktop.privacyAdd')}</li>
          <li>{t('desktop.privacyNever')}</li>
        </ul>
      </Section>

      <div className={styles.group}>
        <div className={cx(styles.row, styles.rowStatic)}>
          <span className={styles.label}>{mac ? t('desktop.aboutMac') : t('desktop.aboutWindows')}</span>
          <span className={styles.valueSmall}>{held.version}</span>
        </div>
      </div>

      <StatusLine status={status} failed={failed} />
    </SubPage>
  );
}

/**
 * The shortcut and a Change button. While recording, the next key press with
 * a modifier becomes the shortcut; Esc keeps the old one. The core registers
 * the new one first and refuses one another app holds, keeping the old.
 */
function ShortcutRow({
  shortcut,
  mac,
  onSave,
}: {
  shortcut: string;
  mac: boolean;
  onSave: (accelerator: string) => Promise<void>;
}): React.JSX.Element {
  const [recording, setRecording] = useState(false);
  const [note, setNote] = useState<{ text: string; bad: boolean } | undefined>();

  useEffect(() => {
    if (!recording) return;
    const listener = (event: KeyboardEvent): void => {
      event.preventDefault();
      event.stopPropagation();
      if (event.key === 'Escape') {
        setRecording(false);
        setNote(undefined);
        return;
      }
      const accelerator = acceleratorOf(event, mac);
      if (accelerator === undefined) return;
      setRecording(false);
      onSave(accelerator)
        .then(() => {
          setNote({ text: t('desktop.shortcutSaved'), bad: false });
        })
        .catch((cause: unknown) => {
          setNote({
            text: cause === 'taken' ? t('desktop.shortcutTaken') : t('desktop.shortcutFailed'),
            bad: true,
          });
        });
    };
    document.addEventListener('keydown', listener, true);
    return () => {
      document.removeEventListener('keydown', listener, true);
    };
  }, [recording, mac, onSave]);

  return (
    <>
      <div className={cx(styles.row, styles.rowStatic)}>
        <span className={styles.label}>{t('desktop.shortcut')}</span>
        <span className={styles.value}>
          <kbd>{recording ? t('desktop.shortcutPress') : prettyShortcut(shortcut, mac)}</kbd>
        </span>
        <button
          type="button"
          className={styles.inlineButton}
          disabled={recording}
          onClick={() => {
            setNote({
              text: mac ? t('desktop.shortcutHintMac') : t('desktop.shortcutHintWindows'),
              bad: false,
            });
            setRecording(true);
          }}
        >
          {t('desktop.shortcutChange')}
        </button>
      </div>
      {note !== undefined && (
        <div className={cx(styles.row, styles.rowStatic)}>
          <span className={cx(styles.valueSmall, note.bad && styles.danger)} role="status">
            {note.text}
          </span>
        </div>
      )}
    </>
  );
}
