import { useRef, useState } from 'react';
import { notebooks as notebooksApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { Confirm } from '@/components/ui/Confirm.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { localTimeZone } from '@/lib/format.js';
import { platform } from '@/lib/platform/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { listWords } from '@/db/repo.js';
import { importWords, resetProgress } from '@/db/mutations.js';
import { syncSoon, useSync } from '@/sync/store.js';
import { LOADING, loadSettingsScreen, wordListText } from './data.js';
import { isSqlite, waitForImport } from './importJob.js';
import { Section, StatusLine, SubPage } from './SettingsKit.js';
import { buildExport, exportFilename } from './transfer/export.js';
import { ImportError, parseFile, withoutDuplicates } from './transfer/parse.js';
import { useSay } from './useSay.js';
import styles from './Settings.module.css';
import { trackWords } from '@/features/celebrate/state.js';

/**
 * Import & export: words in from a file (a Lexpad export, a CSV from Anki
 * or Quizlet, a Kindle's clippings or vocab.db), words out as a list or a
 * whole export, the sync that carries them to the account, and resetting
 * progress, which asks first.
 */
export function DataSettings(): React.JSX.Element {
  const { notebook } = useLiveQuery(loadSettingsScreen, LOADING, []);
  const { phase, queued, parked, syncNow, retryParked } = useSync();
  const { status, failed, say } = useSay();
  const [busy, setBusy] = useState(false);
  const [confirmReset, setConfirmReset] = useState(false);
  const fileInput = useRef<HTMLInputElement>(null);

  const copyList = async (): Promise<void> => {
    if (!notebook) return;
    try {
      await platform.share.text(await wordListText(notebook.id));
      say(t('settings.copied'));
    } catch {
      say(t('settings.copyFailed'), true);
    }
  };

  /**
   * A Kindle's vocab.db is SQLite, which the browser cannot read and which
   * there is no reason to teach it: the server already parses it, so that
   * one file is sent rather than opened here. Everything else is read on
   * this device, offline, as it always was.
   */
  const runKindleUpload = async (file: File): Promise<void> => {
    if (!notebook) return;
    setBusy(true);
    say(t('settings.importSending'));
    try {
      const job = await notebooksApi.importFile(notebook.id, 'kindle', file);
      const done = await waitForImport(job.id);
      if (done.status === 'failed') {
        say(t('settings.importUnreadable'), true);
        return;
      }
      // The words were written on the server, so this device only has them
      // once it has pulled.
      await syncNow();
      const added = done.rowsImported ?? 0;
      const skipped = done.rowsSkipped ?? 0;
      say(
        skipped === 0
          ? t('settings.imported', { added })
          : t('settings.importedWithSkips', { added, skipped }),
      );
    } catch (cause) {
      say(isApiError(cause, 'offline') ? t('settings.importNeedsNetwork') : t('error.generic'), true);
    } finally {
      setBusy(false);
    }
  };

  const runImport = async (file: File): Promise<void> => {
    if (!notebook) return;
    if (await isSqlite(file)) {
      await runKindleUpload(file);
      return;
    }
    setBusy(true);
    say(t('settings.importing'));
    try {
      const parsed = parseFile(file.name, await file.text());
      const existing = (await listWords(notebook.id)).map((word) => word.headword);
      const rows = withoutDuplicates(parsed.rows, existing);
      if (rows.length === 0) {
        say(t('settings.importNothing'), true);
        return;
      }
      const added = await trackWords(() => importWords(notebook.id, rows, localTimeZone()));
      const skipped = parsed.skipped + (parsed.rows.length - rows.length);
      say(
        skipped === 0
          ? t('settings.imported', { added })
          : t('settings.importedWithSkips', { added, skipped }),
      );
      void syncSoon();
    } catch (cause) {
      say(cause instanceof ImportError ? t('settings.importUnreadable') : t('error.generic'), true);
    } finally {
      setBusy(false);
    }
  };

  /**
   * Hands the file to the share sheet where there is one, and falls back to
   * a download. This is the copy somebody keeps; sharing the notebook (on
   * the Notebooks page) is a link to the living notebook, a different thing
   * to want.
   */
  const runExport = async (): Promise<void> => {
    if (!notebook) return;
    setBusy(true);
    try {
      const file = await buildExport(notebook);
      await platform.share.file(exportFilename(notebook), 'application/json', JSON.stringify(file, null, 2));
      say(t('settings.exported'));
    } catch {
      say(t('settings.exportFailed'), true);
    } finally {
      setBusy(false);
    }
  };

  return (
    <SubPage title={t('settings.page.data')}>
      <Section title={t('settings.importHeading')}>
        <div className={styles.group}>
          <button
            type="button"
            className={cx(styles.row, styles.button)}
            disabled={notebook === undefined || busy}
            onClick={() => {
              fileInput.current?.click();
            }}
          >
            {/* Stacked, not side by side: a long description opposite a
                two-word label squeezed the label into a column narrow
                enough to break "Import words" across two lines. */}
            <span className={styles.labelStack}>
              <span className={styles.label}>{t('settings.import')}</span>
              <span className={styles.valueSmall}>{t('settings.importFormats')}</span>
            </span>
          </button>
        </div>
        {/* Outside the card, so the row above it stays its last child. */}
        <input
          ref={fileInput}
          type="file"
          accept=".json,.csv,.tsv,.txt,.db,application/json,text/csv"
          hidden
          aria-label={t('settings.import')}
          onChange={(event) => {
            const file = event.target.files?.[0];
            event.target.value = '';
            if (file) void runImport(file);
          }}
        />
      </Section>

      <Section title={t('settings.exportHeading')}>
        <div className={styles.group}>
          <button
            type="button"
            className={cx(styles.row, styles.button)}
            disabled={notebook === undefined || busy}
            onClick={() => {
              void copyList();
            }}
          >
            <span className={styles.label}>{t('settings.copyList')}</span>
            <span className={styles.valueSmall}>{t('settings.copyNote')}</span>
          </button>
          <button
            type="button"
            className={cx(styles.row, styles.button)}
            disabled={notebook === undefined || busy}
            onClick={() => {
              void runExport();
            }}
          >
            <span className={styles.label}>{t('settings.export')}</span>
            <span className={styles.valueSmall}>{t('settings.exportNote')}</span>
          </button>
        </div>
      </Section>

      <Section title={t('settings.syncHeading')}>
        <div className={styles.group}>
          <button
            type="button"
            className={cx(styles.row, styles.button)}
            disabled={phase === 'syncing'}
            onClick={() => {
              void syncNow();
            }}
          >
            <span className={styles.label}>{t('settings.syncNow')}</span>
            <span className={styles.valueSmall}>{syncLabel(phase, queued)}</span>
          </button>
          {parked > 0 && (
            <button
              type="button"
              className={cx(styles.row, styles.button)}
              disabled={phase === 'syncing'}
              onClick={() => {
                void retryParked();
              }}
            >
              <span className={styles.label}>{t('settings.parked', { count: parked })}</span>
              <span className={styles.valueSmall}>{t('settings.retryParked')}</span>
            </button>
          )}
        </div>
        <p className={styles.dataNote}>{t('settings.dataNote')}</p>
      </Section>

      <div className={styles.group}>
        <button
          type="button"
          className={cx(styles.row, styles.button)}
          onClick={() => {
            setConfirmReset(true);
          }}
        >
          <span className={cx(styles.label, styles.danger)}>{t('settings.reset')}</span>
        </button>
      </div>

      <StatusLine status={status} failed={failed} />

      {confirmReset && (
        <Confirm
          title={t('settings.resetTitle')}
          body={t('settings.resetBody')}
          confirmLabel={t('settings.reset')}
          danger
          onCancel={() => {
            setConfirmReset(false);
          }}
          onConfirm={() => {
            setConfirmReset(false);
            void resetProgress(localTimeZone())
              .then(() => {
                say(t('settings.resetDone'));
                void syncSoon();
              })
              .catch(() => {
                say(t('error.generic'), true);
              });
          }}
        />
      )}
    </SubPage>
  );
}

function syncLabel(phase: string, queued: number): string {
  if (phase === 'syncing') return t('state.syncing');
  if (phase === 'offline') return t('state.offlineSaved');
  if (phase === 'busy') return t('state.busySaved');
  if (phase === 'error') return t('error.generic');
  return queued > 0 ? t('settings.queued', { count: queued }) : t('state.synced');
}
