/**
 * Handing the notebook back to the user.
 *
 * The file is a plain, self-describing JSON document: the notebook, its
 * words with their learning state, the day history and the settings. It is
 * also what `parseLexpad` reads, so an export can be imported again.
 *
 * Version 2 (SRS v2 phase C) adds the notebook's schedule as this learner
 * saved it (Boxes or Smart, the target and the rest), and each word's
 * learning state keeps the memory the server worked out (stabilityE4,
 * difficultyE4, lapses): the learner's own data, whole. An import reads
 * versions 1 and 2 and never takes the stability, the difficulty or the
 * schedule from a file:
 * the server keeps the memory, and a notebook's schedule is changed only on
 * its page.
 */
import { dayIndex } from '@lexpad/core';
import type { DayStat, Settings, Streak, Word } from '@lexpad/core';
import { listWords, loadHistory, loadSavedSchedule, loadSettings, loadStreak } from '@/db/repo.js';
import type { StoredNotebook, StoredSchedule } from '@/db/schema.js';
import { localTimeZone } from '@/lib/format.js';

/** How much history an export carries. A year is plenty for a chart. */
const HISTORY_DAYS = 365;

export interface ExportFile {
  format: 'lexpad';
  version: 2;
  exportedAt: string;
  notebook: {
    title: string;
    targetLang: string;
    meaningLang: string;
    /** This learner's saved schedule for the notebook; absent when nothing was saved. */
    schedule?: Omit<StoredSchedule, 'notebookId'>;
  };
  words: Word[];
  streak: Streak;
  history: DayStat[];
  settings: Settings | null;
}

export async function buildExport(notebook: StoredNotebook, now: Date = new Date()): Promise<ExportFile> {
  const timeZone = localTimeZone();
  const history = await loadHistory(HISTORY_DAYS, timeZone, now);
  const saved = await loadSavedSchedule(notebook.id);
  let schedule: Omit<StoredSchedule, 'notebookId'> | undefined;
  if (saved !== undefined) {
    const { notebookId: _notebookId, ...fields } = saved;
    schedule = fields;
  }
  return {
    format: 'lexpad',
    version: 2,
    exportedAt: now.toISOString(),
    notebook: {
      title: notebook.title,
      targetLang: notebook.targetLang,
      meaningLang: notebook.meaningLang,
      ...(schedule === undefined ? {} : { schedule }),
    },
    words: await listWords(notebook.id),
    streak: await loadStreak(),
    // Days nothing happened are dropped; the chart fills them back in.
    history: history.filter((day) => day.reviewed > 0 || day.newWords > 0),
    settings: await loadSettings(),
  };
}

/** A filename that sorts by date and says what it holds. */
export function exportFilename(notebook: StoredNotebook, now: Date = new Date()): string {
  const day = dayIso(now);
  const slug = notebook.title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
  return `lexpad-${slug === '' ? 'notebook' : slug}-${day}.json`;
}

function dayIso(now: Date): string {
  // The local calendar day, by the same reckoning the app uses everywhere.
  const day = dayIndex(now, localTimeZone());
  return new Date(day * 86_400_000).toISOString().slice(0, 10);
}
