import { useCallback, useEffect, useRef, useState } from 'react';
import { connections } from '@/api/endpoints.js';
import { Confirm } from '@/components/ui/Confirm.js';
import { isApiError } from '@/api/errors.js';
import type { ApiConnection } from '@/api/types.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { lastSeenLabel } from '@/lib/format.js';
import { familyLabel, selfDeclared } from '@/features/connect/family.js';
import { Icon } from '@/components/ui/Icon.js';
import { platform } from '@/lib/platform/index.js';
import { ConnectAssistantSheet } from './ConnectAssistantSheet.js';
import styles from './Settings.module.css';

type Loaded = ApiConnection[] | 'offline' | 'failed' | undefined;

/**
 * Assistants (ChatGPT, Claude) connected over OAuth and MCP. Read from the
 * server, like the signed-in devices on the Account page: a connection is made in another app
 * and nothing about it lives on this device. They are not sessions, so they
 * get their own list rather than a row under Signed-in devices.
 *
 * Disconnecting signs the assistant out, so it asks first through Confirm
 * (the rule for anything that signs out). There is no Undo: the tokens die
 * on the server, and reconnecting is the assistant asking again, which is
 * the safe way round.
 *
 * Each one is named by its verified family (ChatGPT, Claude, an app on this
 * computer), not by the name it registered with, which is anybody's to
 * choose; that name is shown underneath as what it calls itself.
 *
 * The first row opens the steps for connecting one. The connection is made
 * in the assistant, usually in another tab or app, so the list is read again
 * when the sheet closes and whenever the app comes back to the foreground:
 * a new connection shows up without a manual refresh.
 */
export function ConnectedApps({
  say,
  title,
}: {
  say: (message: string, isError?: boolean) => void;
  /** A heading over the list, where the page around it has none of its own. */
  title?: string | undefined;
}): React.JSX.Element {
  const [apps, setApps] = useState<Loaded>();
  const [busy, setBusy] = useState<string | undefined>();
  const [asking, setAsking] = useState<ApiConnection | undefined>();
  const [connecting, setConnecting] = useState(false);
  const live = useRef(true);

  const load = useCallback((): void => {
    connections
      .list()
      .then((list) => {
        if (live.current) setApps(list);
      })
      .catch((cause: unknown) => {
        if (live.current) setApps(isApiError(cause, 'offline') ? 'offline' : 'failed');
      });
  }, []);

  useEffect(() => {
    live.current = true;
    load();
    const onVisible = (): void => {
      if (document.visibilityState === 'visible') load();
    };
    document.addEventListener('visibilitychange', onVisible);
    const offResume = platform.lifecycle.onResume(load);
    return () => {
      live.current = false;
      document.removeEventListener('visibilitychange', onVisible);
      offResume();
    };
  }, [load]);

  const disconnect = (app: ApiConnection): void => {
    setBusy(app.id);
    connections
      .revoke(app.id)
      .then(() => {
        setApps((current) =>
          Array.isArray(current) ? current.filter((each) => each.id !== app.id) : current,
        );
        say(t('settings.appDisconnected', { app: familyLabel(app.knownClient) }));
      })
      .catch((cause: unknown) => {
        say(isApiError(cause, 'offline') ? t('settings.connectedAppsOffline') : t('error.generic'), true);
      })
      .finally(() => {
        setBusy(undefined);
        setAsking(undefined);
      });
  };

  return (
    <section className={styles.section} aria-label={t('settings.connectedApps')}>
      {title !== undefined && <h2 className={styles.sectionTitle}>{title}</h2>}
      <div className={styles.group}>
        <button
          type="button"
          className={cx(styles.row, styles.button)}
          onClick={() => {
            setConnecting(true);
          }}
        >
          <span className={cx(styles.label, styles.connectLabel)}>{t('settings.connectAssistant')}</span>
          <Icon name="chevronRight" size={18} weight={2} />
        </button>
        {(apps === 'offline' || apps === 'failed' || (Array.isArray(apps) && apps.length === 0)) && (
          <div className={cx(styles.row, styles.rowStatic)}>
            <span className={cx(styles.valueSmall, styles.rowMessage)}>
              {apps === 'offline'
                ? t('settings.connectedAppsOffline')
                : apps === 'failed'
                  ? t('settings.connectedAppsFailed')
                  : t('settings.connectedAppsNone')}
            </span>
          </div>
        )}
        {Array.isArray(apps) &&
          apps.map((app) => {
            const calls = selfDeclared(app.clientName, app.knownClient);
            return (
              <div key={app.id} className={cx(styles.row, styles.rowStatic)}>
                <span className={styles.deviceText}>
                  <span className={styles.label}>{familyLabel(app.knownClient)}</span>
                  {calls !== undefined && (
                    <span className={styles.valueSmall} dir="auto">
                      {t('settings.connectedAppCalls', { name: calls })}
                    </span>
                  )}
                  <span className={styles.valueSmall}>
                    {app.lastUsedAt === undefined
                      ? t('settings.connectedAppHostNever', { host: app.redirectHost })
                      : t('settings.connectedAppHost', {
                          host: app.redirectHost,
                          when: lastSeenLabel(app.lastUsedAt),
                        })}
                  </span>
                </span>
                <button
                  type="button"
                  className={styles.inlineButton}
                  aria-label={t('settings.disconnectAppLabel', { app: familyLabel(app.knownClient) })}
                  disabled={busy === app.id}
                  onClick={() => {
                    setAsking(app);
                  }}
                >
                  {t('settings.disconnectApp')}
                </button>
              </div>
            );
          })}
      </div>
      <p className={styles.dataNote}>{t('settings.connectedAppsNote')}</p>
      {connecting && (
        <ConnectAssistantSheet
          say={say}
          onClose={() => {
            setConnecting(false);
            load();
          }}
        />
      )}
      {asking !== undefined && (
        <Confirm
          title={t('settings.disconnectAppTitle', { app: familyLabel(asking.knownClient) })}
          body={t('settings.disconnectAppBody')}
          confirmLabel={t('settings.disconnectApp')}
          busy={busy === asking.id}
          onCancel={() => {
            setAsking(undefined);
          }}
          onConfirm={() => {
            disconnect(asking);
          }}
        />
      )}
    </section>
  );
}
