import { FREEZE_EVERY, MAX_FREEZES, type Streak } from '@lexpad/core';
import { loadStreak } from '@/db/repo.js';
import { shows } from '@/features/schedule/data.js';
import { Section, StatusLine, SwitchRow } from '@/features/settings/SettingsKit.js';
import { t } from '@/i18n/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { useFreezeSwitch } from './useFreezeSwitch.js';
import styles from '@/features/settings/Settings.module.css';

/**
 * Settings → Practice: the streak freeze switch (SRS v2 phase E, spec 3.6
 * and 6.10). It appears only when the srs_v2 feature streakFreeze is on.
 * Turning it on needs every app of the account to be new enough, because
 * the streak is also worked out on each device and an older one would show
 * a broken streak the server kept; until then the row says so and the
 * switch rests. The switch is the server's (`PUT /me/streak-freeze`), so it
 * needs a connection, and a refusal changes nothing here.
 */
export function StreakFreezeRow(): React.JSX.Element | null {
  const streak = useLiveQuery<Streak | undefined>(loadStreak, undefined, []);
  const { srs, online, saving, older, status, failed, change } = useFreezeSwitch();

  if (!shows(srs, 'streakFreeze') || streak === undefined) return null;
  const on = streak.freezeOn === true;
  // Turning off is always allowed; turning on waits for the other apps.
  const blocked = !on && older;

  return (
    <Section title={t('streakFreeze.title')}>
      <div className={styles.group}>
        <SwitchRow
          label={t('streakFreeze.title')}
          checked={on}
          disabled={saving || !online || blocked}
          onChange={(next) => {
            void change(next);
          }}
        />
        <p className={styles.groupNote}>{t('streakFreeze.note', { days: FREEZE_EVERY, max: MAX_FREEZES })}</p>
        {blocked && <p className={styles.groupNote}>{t('streakFreeze.olderDevices')}</p>}
        {!online && !blocked && <p className={styles.groupNote}>{t('streakFreeze.offline')}</p>}
      </div>
      <StatusLine status={status === '' ? undefined : status} failed={failed} />
    </Section>
  );
}
