import { Link, useMatch } from 'react-router-dom';
import { usePane } from '@/components/layout/pane.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { platform } from '@/lib/platform/index.js';
import { useInstallPrompt } from '@/lib/useInstallPrompt.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { useKeepScroll } from '@/lib/useKeepScroll.js';
import { useAuth } from '@/features/auth/session.js';
import { useBilling } from '@/features/billing/state.js';
import { LOADING, loadSettingsScreen } from './data.js';
import { AppearanceControls } from './AppearanceSettings.js';
import { ConnectedApps } from './ConnectedApps.js';
import { PlanControls } from './PlanSettings.js';
import { NavRow, Section, StatusLine } from './SettingsKit.js';
import { SETTINGS_ROOT, settingsPath } from './paths.js';
import { usePlanOnOpen } from './usePlanOnOpen.js';
import { useSay } from './useSay.js';
import styles from './Settings.module.css';

/**
 * Settings: the account at the top and one row for each page, the way a
 * phone's own settings are laid out. It used to be a single page of nine
 * sections and some thirty-five rows; each of those now lives on the page
 * its row opens, and nothing was left behind.
 *
 * Each row says what is behind it where that fits in a word or two — the
 * reminder's time, the notebook — so the page answers the common question
 * without being opened.
 *
 * Three things are used often enough to sit here rather than behind a row
 * (owner's call, 2026-10-04): the theme, the connected assistants and the
 * plan. Their pages still exist for links that name them.
 */
export function Settings(): React.JSX.Element {
  const data = useLiveQuery(loadSettingsScreen, LOADING, []);
  const { status, failed, say } = useSay();
  const user = useAuth((state) => state.user);
  const plan = useBilling((state) => state.state);
  const install = useInstallPrompt();
  usePlanOnOpen();

  const { settings, notebook, notebooks } = data;
  // Nothing about the plan is shown until the server has said what it is: a
  // paying learner briefly shown "Free" is worse than a moment of nothing.
  const planName =
    plan === null ? undefined : plan.plan === 'pro' ? t('upgrade.planProOpen') : t('upgrade.planFree');
  const name = user?.displayName.trim() ?? '';
  // Beside the page it opens, on an expanded window: the split view owns the
  // page's <main>, and Settings on its own shows the account page beside
  // the list, so the account card is the current row.
  const pane = usePane();
  // Back from one of its pages lands where the reader was. Beside a page,
  // on an expanded window, the list never left, so there is nothing to do.
  useKeepScroll(pane === undefined);
  const Root = pane === undefined ? 'main' : 'div';
  const atRoot = useMatch(SETTINGS_ROOT) !== null;
  const atAccount = useMatch(settingsPath('account')) !== null;

  return (
    <Root className={styles.screen}>
      <div className={styles.head}>
        <h1 className={styles.title}>{t('settings.title')}</h1>
      </div>

      <Link
        to={settingsPath('account')}
        className={styles.accountCard}
        aria-current={atAccount || (pane === 'list' && atRoot) ? 'page' : undefined}
      >
        <span className={styles.avatar} aria-hidden="true">
          {initialOf(name === '' ? (user?.email ?? '') : name)}
        </span>
        <span className={styles.accountText}>
          <span className={styles.accountName}>{name === '' ? t('settings.account') : name}</span>
          {user !== null && <span className={styles.accountEmail}>{user.email}</span>}
        </span>
        {planName !== undefined && (
          <span className={cx(styles.badge, plan?.plan === 'pro' && styles.badgePro)}>{planName}</span>
        )}
        <Icon name="chevronRight" size={18} weight={2} className={styles.chevron} />
      </Link>

      {/* Inside the desktop app: its shortcut, permissions, notifications
          and start-up, on a page of their own like everything else here. */}
      {platform.desktop !== undefined && (
        <nav className={styles.group} aria-label={t('settings.page.desktop')}>
          <NavRow to={settingsPath('desktop')} icon="computer" label={t('settings.page.desktop')} />
        </nav>
      )}

      {/* Every place the notebook can be, right under the account: the
          pull side of telling people about the other surfaces. A page of
          its own, like every other group here. */}
      <nav className={styles.group} aria-label={t('everywhere.title')}>
        <NavRow to={settingsPath('everywhere')} icon="grid" label={t('settings.page.everywhere')} />
      </nav>

      <nav className={styles.group} aria-label={t('settings.title')}>
        <NavRow
          to={settingsPath('notebooks')}
          also={settingsPath('schedule')}
          icon="notebook"
          label={t('settings.page.notebooks')}
          value={
            notebooks.length > 1 ? t('settings.notebooksCount', { count: notebooks.length }) : notebook?.title
          }
        />
        <NavRow to={settingsPath('practice')} icon="cards" label={t('settings.page.practice')} />
        <NavRow
          to={settingsPath('notifications')}
          icon="bell"
          label={t('settings.page.notifications')}
          value={
            settings.reminderTime === undefined
              ? t('settings.reminderOff')
              : t('settings.reminderOn', { time: settings.reminderTime })
          }
        />
        <NavRow to={settingsPath('data')} icon="list" label={t('settings.page.data')} />
      </nav>

      <Section title={t('settings.page.appearance')}>
        <AppearanceControls />
      </Section>

      <ConnectedApps say={say} title={t('settings.page.connectedApps')} />

      <Section title={t('settings.page.plan')}>
        <PlanControls />
      </Section>

      <nav className={styles.group} aria-label={t('settings.moreLabel')}>
        <NavRow
          to={settingsPath('about')}
          icon="info"
          label={t('settings.page.about')}
          also={settingsPath('how')}
        />
      </nav>

      <StatusLine status={status} failed={failed} />

      {install.canPrompt && (
        <div className={styles.install}>
          {t('settings.installHint')}
          <div>
            <button
              type="button"
              className={styles.installButton}
              onClick={() => {
                void install.prompt();
              }}
            >
              {t('settings.install')}
            </button>
          </div>
        </div>
      )}
      {install.iosHint && <div className={styles.install}>{t('settings.installIos')}</div>}
    </Root>
  );
}

/** The first letter of a name, for the round mark on the account card. */
function initialOf(text: string): string {
  const first = Array.from(text.trim())[0];
  return first === undefined ? '' : first.toLocaleUpperCase();
}
